using System.Collections.Generic;
using System.Linq;
using UnityEngine;

public class Destructible : Entity
{
	public class DestructibleIdleState : State<Destructible>
	{
		public DestructibleIdleState(string stateName, FSM parentFSM, Destructible parentEntity)
			: base(stateName, parentFSM, parentEntity)
		{
		}
	}

	public class DestructibleDeadState : State<Destructible>
	{
		public DestructibleDeadState(string stateName, FSM parentFSM, Destructible parentEntity)
			: base(stateName, parentFSM, parentEntity)
		{
		}

		public override void OnEnter()
		{
			if (parent.dropLoot && parent.health != null && parent.health.lastAttack != null && !parent.health.lastAttack.skillCategory.Contains("Player"))
			{
				parent.dropLoot = false;
			}
			parent.Break();
			if (parent.autoDestroyOnDeath && parent.gameObject != null)
			{
				Object.Destroy(parent.gameObject, parent.autoDestroyDelay);
			}
		}
	}

	public class DestructibleHurtState : HurtState
	{
		public DestructibleHurtState(string stateName, FSM parentFSM, Destructible parentEntity)
			: base(stateName, parentFSM, parentEntity)
		{
			playHurtAnim = false;
		}
	}

	public bool destroyed;

	public string destroyedAudioID;

	public bool autoDestroyOnDeath;

	public float autoDestroyDelay = 1.4f;

	public bool hideSpritesOnBreak;

	public bool disableCollidersOnBreak;

	public bool useFacingDirOverride;

	public FacingDirection facingDirOverride;

	public bool emitParticleEffectOnBreak;

	public string particleEffectName = string.Empty;

	public int particleCount;

	public Vector3 breakParticleOffset;

	public bool dropLoot = true;

	public string lootTableName = "Destructible";

	protected Vector3 lootDropOffset = Vector3.zero;

	public Transform subObjectTrans;

	public Destructible[] subObjDestructibles;

	public GameObject[] subObjs;

	protected Collider2D[] colliders;

	protected SpriteRenderer[] spriteRenderers;

	protected string incColliderName = string.Empty;

	protected bool allyContact;

	public bool destroyOnContact = true;

	public bool destroyScriptOnBreak;

	public override void Awake()
	{
		disablePreventFallCollider = true;
		base.Awake();
		destroyed = false;
		colliders = GetComponentsInChildren<Collider2D>();
		spriteRenderers = GetComponentsInChildren<SpriteRenderer>();
		Transform transform = base.transform.Find("DestructibleSprite") ?? base.transform.Find("Sprite");
		if (transform != null)
		{
			spriteRenderer = transform.GetComponent<SpriteRenderer>();
		}
		else
		{
			spriteRenderer = GetComponentInChildren<SpriteRenderer>();
		}
		InitFSM();
	}

	public override void InitComponents()
	{
		base.InitComponents();
		if (health != null)
		{
			health.ignoreSlow.Modify(Health.baseIgnoreMod, addMod: true);
			health.ignorePoison.Modify(Health.baseIgnoreMod, addMod: true);
			health.ignoreFreeze.Modify(Health.baseIgnoreMod, addMod: true);
		}
	}

	public virtual void InitFSM()
	{
		fsm = new FSM();
		fsm.defaultStateName = "Idle";
		fsm.AddState(new DestructibleIdleState("Idle", fsm, this));
		fsm.AddState(new DestructibleDeadState("Dead", fsm, this));
		fsm.AddState(new DestructibleHurtState("Hurt", fsm, this));
		fsm.ChangeState(fsm.defaultStateName);
	}

	public override void Start()
	{
		base.Start();
		if (useFacingDirOverride)
		{
			facingDirection = facingDirOverride;
			if (facingDirection == FacingDirection.Left)
			{
				isFacingRight = true;
			}
			else
			{
				isFacingRight = false;
			}
		}
		subObjectTrans = base.transform.Find("SubObjects");
		if (subObjectTrans != null)
		{
			List<GameObject> list = new List<GameObject>();
			foreach (Transform subObjectTran in subObjectTrans)
			{
				list.Add(subObjectTran.gameObject);
			}
			subObjDestructibles = subObjectTrans.GetComponentsInChildren<Destructible>();
			for (int i = 0; i < subObjDestructibles.Length; i++)
			{
				list.Remove(subObjDestructibles[i].gameObject);
				if (subObjDestructibles[i].hurtBoxCollider != null)
				{
					subObjDestructibles[i].hurtBoxCollider.gameObject.SetActive(value: false);
				}
				if (subObjDestructibles[i].floorCollider != null)
				{
					subObjDestructibles[i].floorCollider.gameObject.SetActive(value: false);
				}
			}
			subObjs = list.ToArray();
		}
		if (health != null)
		{
			health.entitySprites = new List<SpriteRenderer>();
			health.entitySprites = health.entitySprites.Where((SpriteRenderer y) => !y.gameObject.name.Contains("Shadow")).ToList();
			health.entitySprites.AddRange(GetComponentsInChildren<SpriteRenderer>());
		}
	}

	public virtual void Reset()
	{
		destroyed = false;
		if (anim != null)
		{
			anim.Play("Idle");
		}
		transform.position = myOrigin;
	}

	public void DestroySubObjects(int maxRetry = 4)
	{
		if (subObjDestructibles != null)
		{
			for (int i = 0; i < subObjDestructibles.Length; i++)
			{
				if (subObjDestructibles[i] != null)
				{
					subObjDestructibles[i].Break();
				}
			}
		}
		if (subObjs != null)
		{
			for (int j = 0; j < subObjs.Length; j++)
			{
				Object.Destroy(subObjs[j]);
			}
		}
	}

	public void EmitParticlesOnBreak()
	{
		if (emitParticleEffectOnBreak && particleCount > 0 && particleEffectName != string.Empty)
		{
			PoolManager.GetPoolItem<ParticleEffect>(particleEffectName).Emit(particleCount, hurtBoxTransform.position + breakParticleOffset);
		}
	}

	public virtual void Break()
	{
		if (health != null)
		{
			ApplyKnockback(health.lastAttack);
		}
		destroyed = true;
		if (anim != null)
		{
			anim.Play("Destroyed");
		}
		if (hideSpritesOnBreak)
		{
			for (int i = 0; i < spriteRenderers.Length; i++)
			{
				if (spriteRenderers[i] != null)
				{
					spriteRenderers[i].enabled = false;
				}
			}
		}
		if (disableCollidersOnBreak)
		{
			for (int j = 0; j < colliders.Length; j++)
			{
				if (colliders[j] != null)
				{
					colliders[j].enabled = false;
				}
			}
		}
		if (destroyedAudioID != string.Empty)
		{
			string audioID = destroyedAudioID;
			Vector2? soundOrigin = transform.position;
			float overridePitch = Random.Range(0.8f, 1.2f);
			SoundManager.PlayAudioWithDistance(audioID, soundOrigin, null, 24f, -1f, overridePitch);
		}
		if (dropLoot && (allyContact || (health != null && health.lastAttack != null && health.lastAttack.skillCategory.Contains("Player"))))
		{
			LootManager.DropLoot(lootTableName, transform.position + lootDropOffset);
		}
		EmitParticlesOnBreak();
		if (destroyScriptOnBreak)
		{
			Object.Destroy(this);
		}
		DestroySubObjects();
	}

	public virtual void OnTriggerEnter2D(Collider2D col)
	{
		if (destroyOnContact && !destroyed && col != null)
		{
			incColliderName = col.gameObject.name;
			allyContact = incColliderName == Globals.allyFCStr;
			if (allyContact || incColliderName == Globals.enemyFCStr)
			{
				Vector3 position = col.transform.position;
				CameraController.ShakeCamera(0.125f);
				PoolManager.GetPoolItem<HitSparkEmitter>().EmitSingle(HitSparkType.Small, position, position);
				string audioID = "ImpactPhysicalLight";
				Vector2? soundOrigin = position;
				float standardPitchRange = SoundManager.StandardPitchRange;
				SoundManager.PlayAudioWithDistance(audioID, soundOrigin, null, 24f, -1f, standardPitchRange);
				Break();
			}
		}
	}
}
using UnityEngine;

public class WoodDestructible : Destructible
{
	public class WoodDestructibleHurtState : DestructibleHurtState
	{
		public new WoodDestructible parent;

		public WoodDestructibleHurtState(string newName, FSM newFSM, WoodDestructible newEntity)
			: base(newName, newFSM, newEntity)
		{
			parent = newEntity;
		}

		public override void OnEnter()
		{
			base.OnEnter();
			parent.ShowElementalEffect();
		}
	}

	public int woodBreakParticleCount = 30;

	public override void Awake()
	{
		base.Awake();
		if (destroyedAudioID == string.Empty)
		{
			destroyedAudioID = "WoodBreak";
		}
	}

	public override void InitFSM()
	{
		base.InitFSM();
		fsm.ReplaceState(new WoodDestructibleHurtState("Hurt", fsm, this));
	}

	public override void Break()
	{
		base.Break();
		ShowElementalEffect(10);
		if (woodBreakParticleCount > 0)
		{
			PoolManager.GetPoolItem<WoodBreakEffect>("WoodBreakEffect").EmitSingle(woodBreakParticleCount, hurtBoxTransform.position);
		}
	}

	public void ShowElementalEffect(int particleCount = 5)
	{
		ElementType elementType = element;
		if (elementType == ElementType.Water)
		{
			PoolManager.GetPoolItem<ParticleEffect>("SnowDebrisEmitter").Emit(particleCount, transform.position + Vector3.up);
		}
		if (this is Painting)
		{
			switch (element)
			{
			case ElementType.Water:
				PoolManager.GetPoolItem<ParticleEffect>("SnowDebrisEmitter").Emit(particleCount, transform.position - Vector3.up + Vector3.right);
				break;
			case ElementType.Fire:
				PoolManager.GetPoolItem<ParticleEffect>("MetalDebrisEmitter").Emit(particleCount, transform.position - Vector3.up + Vector3.right);
				PoolManager.GetPoolItem<ParticleEffect>("MetalSparkEmitter").Emit(particleCount, transform.position - Vector3.up + Vector3.right);
				woodBreakParticleCount = 0;
				break;
			case ElementType.Lightning:
				PoolManager.GetPoolItem<ParticleEffect>("MetalDebrisEmitter").Emit(particleCount, transform.position - Vector3.up + Vector3.right);
				PoolManager.GetPoolItem<ParticleEffect>("MetalSparkEmitter").Emit(particleCount, transform.position - Vector3.up + Vector3.right);
				woodBreakParticleCount = 0;
				break;
			}
		}
	}
}
using UnityEngine;

public class Pot : Destructible
{
	private ParticleSystem debrisEmitter;

	public override void Awake()
	{
		base.Awake();
		debrisEmitter = transform.Find("DebrisEmitter").GetComponent<ParticleSystem>();
	}

	public override void Break()
	{
		if (!destroyed)
		{
			base.Break();
			transform.localEulerAngles = Vector3.zero;
			debrisEmitter.Emit(8);
			for (int i = 0; i < health.entitySprites.Count; i++)
			{
				health.entitySprites[i].enabled = false;
			}
			for (int j = 0; j < colliders.Length; j++)
			{
				colliders[j].enabled = false;
			}
			Object.Destroy(gameObject, 3f);
		}
	}
}
using System.Collections;
using UnityEngine;

public class ExplosiveBarrel : Destructible
{
	public static BoolVarStat ignorePlayerStat = new BoolVarStat(newBaseVal: false);

	private float explodeDelay = 0.25f;

	private float explodeScale = 2.25f;

	public override void Awake()
	{
		base.Awake();
		if (destroyedAudioID == string.Empty)
		{
			destroyedAudioID = "WoodBreak";
		}
	}

	public override void InitFSM()
	{
		base.InitFSM();
		fsm.AddState(new FallState("Fall", fsm, this));
	}

	public override void Break()
	{
		if (health != null)
		{
			ApplyKnockback(health.lastAttack);
			health.lastAttack = null;
		}
		StartCoroutine(DelayedExplosion());
	}

	private IEnumerator DelayedExplosion()
	{
		yield return new WaitForSeconds(explodeDelay);
		if (!(fsm.currentStateName == "Fall"))
		{
			if (ignorePlayerStat.CurrentValue)
			{
				FlameBurst.CreateBurst(transform.position, Enemy.globalEnemySkillCategory, "HazardExplosiveBarrelEnemyOnly", 1, explodeScale);
			}
			else
			{
				FlameBurst.CreateBurst(transform.position, "EnemyFFA", "HazardExplosiveBarrel", 1, explodeScale);
			}
			PoolManager.GetPoolItem<ParticleEffect>("BurnMarkLargeEmitter").Emit(1, transform.position, ParticleEffectOverrides.StartLifeTimeOne);
			string audioID = "BlazingBlitzEnd";
			Vector2? soundOrigin = transform.position;
			float standardPitchRange = SoundManager.StandardPitchRange;
			SoundManager.PlayAudioWithDistance(audioID, soundOrigin, null, 24f, -1f, standardPitchRange);
			PoolManager.GetPoolItem<WoodBreakEffect>("WoodBreakEffect").EmitSingle(20, transform.position);
			PoolManager.GetPoolItem<ParticleEffect>("SmokeSmallEmitter").Emit(4, transform.position + Vector3.up * 1.5f);
			PoolManager.GetPoolItem<ParticleEffect>("SmokeSmallEmitter").Emit(4, transform.position + Vector3.up * 2f);
			PoolManager.GetPoolItem<ParticleEffect>("SmokeEmitter").Emit(12, transform.position + Vector3.up * 0.5f);
			PoolManager.GetPoolItem<ParticleEffect>("MetalDebrisEmitter").Emit(6, transform.position + Vector3.up * 0.5f);
			base.Break();
		}
	}
}
using UnityEngine;

public class HealthCrystal : Destructible
{
	private static GameObject prefab;

	public Light light;

	protected static ParticleSystemOverride _crystalShatterOverride;

	public static GameObject Prefab => prefab ?? (prefab = ChaosBundle.Get("Assets/Prefabs/Environment/Destructibles/HealthCrystal.prefab"));

	public static ParticleSystemOverride CrystalShatterOverride
	{
		get
		{
			if (_crystalShatterOverride == null)
			{
				ParticleSystemOverride particleSystemOverride = new ParticleSystemOverride();
				particleSystemOverride.startColor = new Color(1f, 0.45f, 0.55f, 0.75f);
				particleSystemOverride.startLifetime = 0.5f;
				particleSystemOverride.radius = 0.25f;
				particleSystemOverride.startSpeed = 30f;
				_crystalShatterOverride = particleSystemOverride;
			}
			return _crystalShatterOverride;
		}
	}

	public override void Break()
	{
		dropLoot = false;
		base.Break();
		LootManager.DropLoot(lootTableName, transform.position + lootDropOffset);
		Vector2 vector = spriteRenderer.transform.position;
		PoolManager.GetPoolItem<ParticleEffect>("GlassBreakEffect").Emit(2, vector - Vector2.up * 0.5f, CrystalShatterOverride);
		PoolManager.GetPoolItem<ParticleEffect>("GlassBreakEffect").Emit(2, vector + Vector2.up * 0.5f, CrystalShatterOverride);
		PoolManager.GetPoolItem<ParticleEffect>("GlassBreakEffect").Emit(8, vector, CrystalShatterOverride);
		PoolManager.GetPoolItem<ParticleEffect>("GlassBreakEffectLarge").Emit(4, vector, CrystalShatterOverride);
	}
}
using UnityEngine;

public class Icicle : Destructible
{
	private SpriteRenderer floorSpriteRenderer;

	private ParticleSystemOverride pSysSettings;

	public Sprite[] floorSprites;

	internal static GameObject _prefab;

	public static GameObject Prefab
	{
		get
		{
			if (_prefab == null)
			{
				_prefab = ChaosBundle.Get("Assets/Prefabs/Environment/Ice/Icicle.prefab");
			}
			return _prefab;
		}
	}

	public override void Awake()
	{
		base.Awake();
		pSysSettings = new ParticleSystemOverride();
		pSysSettings.startSpeed = 5f;
		pSysSettings.startLifetime = 0.7f;
		pSysSettings.radius = 0.5f;
		spriteRenderer = transform.Find("DestructibleSprite").GetComponent<SpriteRenderer>();
		floorSpriteRenderer = transform.Find("DestructibleFloorSprite").GetComponent<SpriteRenderer>();
	}

	public override void Break()
	{
		base.Break();
		spriteRenderer.enabled = false;
		floorSpriteRenderer.enabled = false;
		hurtBoxTransform.gameObject.SetActive(value: false);
		PoolManager.GetPoolItem<ParticleEffect>("IcicleBreakEffect").Emit(10, transform.position + new Vector3(0f, 2f, 0f), pSysSettings);
		PoolManager.GetPoolItem<ParticleEffect>("IcicleBreakEffect").Emit(10, transform.position + new Vector3(0f, 2f, 0f));
		PoolManager.GetPoolItem<ParticleEffect>("IcicleBreakEffect").Emit(20, transform.position + new Vector3(0f, 1f, 0f));
		PoolManager.GetPoolItem<ParticleEffect>("IcicleBreakEffect").Emit(20, transform.position + new Vector3(0f, 0.4f, 0f));
		SoundManager.PlayAudioWithDistance("Shatter", transform.position);
	}
}
using UnityEngine;

public class Statue : MonoBehaviour
{
	public bool autoSelectElement = true;

	public bool randomizeSprite = true;

	public ElementType element;

	public ElementalSpriteVars statueVars;

	public ElementalSpriteVars baseVars;

	public ElementalSpriteVars floorVars;

	public SpriteRenderer statueRenderer;

	public SpriteRenderer baseRenderer;

	public SpriteRenderer floorRenderer;

	public void Start()
	{
		if (autoSelectElement)
		{
			element = Level.element;
		}
		if (randomizeSprite)
		{
			statueRenderer.sprite = statueVars.GetElementalSprite(element);
			baseRenderer.sprite = baseVars.GetElementalSprite(element);
			floorRenderer.sprite = floorVars.GetElementalSprite(element);
		}
	}
}
using UnityEngine;

public class Tombstone : MonoBehaviour
{
	[HideInInspector]
	public Entity entity;

	private void Update()
	{
		if (entity == null || !entity.fsm.currentStateName.Contains("Dead"))
		{
			Object.Destroy(gameObject);
		}
	}

	public void Instantiate(Entity newEntity, Transform parentTrans)
	{
		entity = newEntity;
		float num = ((Random.Range(0, 2) != 1) ? Random.Range(0.6f, 1f) : Random.Range(-1f, -0.6f));
		float num2 = ((Random.Range(0, 2) != 1) ? Random.Range(0.6f, 1f) : Random.Range(-1f, -0.6f));
		transform.position = new Vector3(parentTrans.position.x + num, parentTrans.position.y + num2, parentTrans.position.z);
	}
}

