using UnityEngine;

public class TreasureChest : Destructible
{
	public class TreasureDeadState : DestructibleDeadState
	{
		public TreasureDeadState(string stateName, FSM parentFSM, TreasureChest parentEntity)
			: base(stateName, parentFSM, parentEntity)
		{
		}

		public override void OnEnter()
		{
			parent.Break();
			if (parent.autoDestroyOnDeath && parent.gameObject != null)
			{
				Object.Destroy(parent.gameObject, parent.autoDestroyDelay);
			}
		}
	}

	private static GameObject prefab;

	private static float elementalChance = 0.1f;

	private static float mimicChance = 0.13f;

	private static float partyChance = 0.02f;

	public static GameObject confettiExplosionPrefab;

	public TreasureChestType chestType;

	public bool opened;

	public bool preventElemental;

	public bool preventMimic;

	protected Vector2 spawnLocation;

	private CompassIndicatorTrigger compassTrigger;

	public static GameObject Prefab => prefab ?? (prefab = ChaosBundle.Get("Assets/Prefabs/Environment/Destructibles/TreasureChest.prefab"));

	public override void InitFSM()
	{
		base.InitFSM();
		fsm.ReplaceState(new TreasureDeadState("Dead", fsm, this));
	}

	public override void Start()
	{
		if (lootTableName == string.Empty || lootTableName == "Destructible")
		{
			lootTableName = "TreasureChest";
		}
		SetChestType();
		if (!opened)
		{
			if (!preventElemental && chestType == TreasureChestType.Standard)
			{
				if (Random.value < partyChance)
				{
					Object.Destroy(gameObject);
					Globals.ChaosInst<TreasureChestParty>(TreasureChestParty.Prefab, transform.parent, transform.position);
					return;
				}
				if (Random.value < elementalChance)
				{
					Object.Destroy(gameObject);
					Globals.ChaosInst<TreasureChestElemental>(TreasureChestElemental.Prefab, transform.parent, transform.position);
					return;
				}
			}
			if (Globals.InGameScene(string.Empty) && !preventMimic && Random.value < mimicChance && (chestType == TreasureChestType.Mini || chestType == TreasureChestType.Standard))
			{
				Object.Destroy(gameObject);
				switch (chestType)
				{
				case TreasureChestType.Mini:
					Enemy.Spawn(Enemy.EName.MimicEnemy, transform.position, transform.parent, dropLoot: true, alerted: false, spawnCard: false);
					break;
				case TreasureChestType.Standard:
					Enemy.Spawn(Enemy.EName.MimicEnemyLarge, transform.position, transform.parent, dropLoot: true, alerted: false, spawnCard: false);
					break;
				}
				return;
			}
		}
		base.Start();
		if (opened)
		{
			anim.Play("OpenIdle" + chestType, -1, 0f);
		}
		else
		{
			anim.Play("Spawning" + chestType, -1, 0f);
			SoundManager.PlayAudioWithDistance("StandardChestSpawn", transform.position);
		}
		if (compassTrigger == null)
		{
			compassTrigger = CompassIndicatorTrigger.Spawn(Compass.CompassIndicatorType.TreasureChest, transform.position, transform, 3f);
		}
	}

	public void SetChestType()
	{
		if (lootTableName.Contains("MiniBoss"))
		{
			chestType = TreasureChestType.MiniBoss;
		}
		else if (lootTableName.Contains("Boss"))
		{
			chestType = TreasureChestType.Boss;
		}
		else if (lootTableName == "TreasureChestSmall")
		{
			chestType = TreasureChestType.Mini;
		}
		else if (lootTableName == "TreasureChestElemental")
		{
			chestType = TreasureChestType.Elemental;
		}
		else
		{
			chestType = TreasureChestType.Standard;
		}
	}

	public override void Update()
	{
		if (!opened)
		{
			base.Update();
			if (destroyed)
			{
				anim.Play("Opened" + chestType);
			}
		}
	}

	public override void OnTriggerEnter2D(Collider2D col)
	{
	}

	public override void Break()
	{
		destroyed = true;
		if (dropLoot)
		{
			spawnLocation = transform.position;
			LootManager.DropLoot(lootTableName, spawnLocation);
			spawnLocation.y += 1.2f;
			PoolManager.GetPoolItem<ConfettiEffect>().EmitSingle(50, spawnLocation);
			SoundManager.PlayAudioWithDistance("StandardChestOpen", spawnLocation);
		}
	}

	public void PlaySpawnEffect()
	{
		PoolManager.GetPoolItem<ParticleEffect>("SparkleAura").Emit(10, spriteRenderer.transform.position - Vector3.up * 0.5f, ParticleEffectOverrides.Radius1p5);
	}
}
public enum TreasureChestType
{
	Standard,
	Mini,
	MiniBoss,
	Boss,
	Elemental,
	Party
}
