public class TreasureChestElemental : TreasureChest
{
	private static GameObject prefab;

	private const int availableElementCount = 5;

	private static ElementType[] availableElements = new ElementType[5]
	{
		ElementType.Fire,
		ElementType.Air,
		ElementType.Earth,
		ElementType.Lightning,
		ElementType.Water
	};

	private const int maxReqIndex = 5;

	private int currentMaxIndex;

	private int currentReqIndex;

	private string currentSkillKey;

	private static Vector3 emoteOffset = new Vector3(0f, 2.25f, 0f);

	public ElementalSpriteSelector eleSpriteSelector;

	private string[] skillUseHistory = new string[5];

	public Sprite[] spriteArray;

	public ElementType[] eleReqArray = new ElementType[5];

	private SpriteRenderer[] eleReqSpriteArray = new SpriteRenderer[5];

	private SpriteRenderer[] eleBaseSpriteArray = new SpriteRenderer[5];

	private Transform eleSpriteTrans;

	private const float eleSpriteYPos = -0.1875f;

	public new static GameObject Prefab => prefab ?? (prefab = ChaosBundle.Get("Assets/Prefabs/Environment/Destructibles/TreasureChestElemental.prefab"));

	public override void Awake()
	{
		base.Awake();
		eleSpriteTrans = transform.Find("Sprite/ElementSprites");
		for (int i = 0; i < 5; i++)
		{
			eleReqSpriteArray[i] = eleSpriteTrans.Find("Sprite" + i + "/ElementIcon").GetComponent<SpriteRenderer>();
			eleBaseSpriteArray[i] = eleSpriteTrans.Find("Sprite" + i + "/BaseSprite").GetComponent<SpriteRenderer>();
		}
	}

	public override void Start()
	{
		base.Start();
		currentMaxIndex = Mathf.Min(3, GameController.CurrentDifficulty + ((!GameController.coopOn) ? 1 : 2));
		for (int i = 0; i < currentMaxIndex; i++)
		{
			eleReqArray[i] = availableElements[UnityEngine.Random.Range(0, 5)];
		}
		for (int j = 0; j < 5; j++)
		{
			skillUseHistory[j] = string.Empty;
			switch (eleReqArray[j])
			{
			case ElementType.Fire:
				eleReqSpriteArray[j].sprite = spriteArray[0];
				continue;
			case ElementType.Air:
				eleReqSpriteArray[j].sprite = spriteArray[1];
				continue;
			case ElementType.Earth:
				eleReqSpriteArray[j].sprite = spriteArray[2];
				continue;
			case ElementType.Lightning:
				eleReqSpriteArray[j].sprite = spriteArray[3];
				continue;
			case ElementType.Water:
				eleReqSpriteArray[j].sprite = spriteArray[4];
				continue;
			}
			eleReqSpriteArray[j].sprite = null;
			eleReqSpriteArray[j].enabled = false;
			eleBaseSpriteArray[j].enabled = false;
		}
		switch (currentMaxIndex)
		{
		case 1:
			eleSpriteTrans.localPosition = new Vector2(1.125f, -0.1875f);
			break;
		case 2:
			eleSpriteTrans.localPosition = new Vector3(0.8125f, -0.1875f);
			break;
		case 3:
			eleSpriteTrans.localPosition = new Vector2(0.5625f, -0.1875f);
			break;
		case 4:
			eleSpriteTrans.localPosition = new Vector2(0.25f, -0.1875f);
			break;
		case 5:
			eleSpriteTrans.localPosition = Vector2.zero;
			break;
		}
		Health health = base.health;
		health.takeDamageEventHandlers = (Health.OnTakeDamageHandler)Delegate.Remove(health.takeDamageEventHandlers, new Health.OnTakeDamageHandler(OnDamageTaken));
		Health health2 = base.health;
		health2.takeDamageEventHandlers = (Health.OnTakeDamageHandler)Delegate.Combine(health2.takeDamageEventHandlers, new Health.OnTakeDamageHandler(OnDamageTaken));
		ResetElementSequence(initializing: true);
	}

	public override void Break()
	{
		destroyed = true;
		if (dropLoot)
		{
			spawnLocation = transform.position;
			eleSpriteSelector.SetElement(ElementType.Neutral);
			for (int i = 0; i < currentMaxIndex + 1; i++)
			{
				LootManager.DropLoot(lootTableName, spawnLocation);
			}
			spawnLocation.y += 1.2f;
			PoolManager.GetPoolItem<ConfettiEffect>().EmitSingle(50, spawnLocation);
			PoolManager.GetPoolItem<ParticleEffect>("MetalDebrisEmitter").Emit(8, spawnLocation);
			SoundManager.PlayAudioWithDistance("StandardChestOpen", spawnLocation);
			if (base.health != null)
			{
				Health health = base.health;
				health.takeDamageEventHandlers = (Health.OnTakeDamageHandler)Delegate.Remove(health.takeDamageEventHandlers, new Health.OnTakeDamageHandler(OnDamageTaken));
			}
		}
	}

	public void OnDamageTaken(AttackInfo givenAtkInfo, Entity givenEnt = null)
	{
		if (destroyed || givenAtkInfo.isStatusEffect)
		{
			return;
		}
		currentSkillKey = givenAtkInfo.skillCategory + givenAtkInfo.skillID;
		for (int i = 0; i < currentReqIndex; i++)
		{
			if (currentSkillKey == skillUseHistory[i])
			{
				return;
			}
		}
		if (givenAtkInfo.elementType == eleReqArray[currentReqIndex] || givenAtkInfo.elementType == ElementType.Chaos)
		{
			AdvanceElementSequence();
		}
		else
		{
			ResetElementSequence();
		}
	}

	private void AdvanceElementSequence()
	{
		skillUseHistory[currentReqIndex] = currentSkillKey;
		eleReqSpriteArray[currentReqIndex].enabled = false;
		currentReqIndex++;
		if (currentReqIndex < currentMaxIndex)
		{
			eleSpriteSelector.SetElement(eleReqArray[currentReqIndex]);
			EmoteEmitter poolItem = PoolManager.GetPoolItem<EmoteEmitter>();
			EmoteType emoteType = EmoteType.Correct;
			Vector3? position = transform.position + emoteOffset;
			poolItem.Emit(emoteType, null, position);
			SoundManager.PlayAudioWithDistance("Correct", transform.position);
		}
		else
		{
			Break();
		}
	}

	private void ResetElementSequence(bool initializing = false)
	{
		currentReqIndex = 0;
		for (int i = 0; i < 5; i++)
		{
			SpriteRenderer obj = eleReqSpriteArray[i];
			bool flag = i < currentMaxIndex;
			eleBaseSpriteArray[i].enabled = flag;
			obj.enabled = flag;
		}
		eleSpriteSelector.SetElement(eleReqArray[0]);
		if (!initializing)
		{
			EmoteEmitter poolItem = PoolManager.GetPoolItem<EmoteEmitter>();
			EmoteType emoteType = EmoteType.Wrong;
			Vector3? position = transform.position + emoteOffset;
			poolItem.Emit(emoteType, null, position);
		}
	}
}
