			HealOnCrit.staticID,
			OutOfCombatCrit.staticID,
			SummonVampiricItem.staticID,
			SuperCritChance.staticID,
			Vampiricism.staticID
		}),
		new Tuple<string[], string[]>(new string[5]
		{
			Player.ShootFireball.staticID,
			Player.UseThrowBoulder.staticID,
			Player.UseShockSpear.staticID,
			Player.ThrowIceLance.staticID,
			Player.UseAirSentry.staticID
		}, new string[3]
		{
			AlwaysWinProjectiles.staticID,
			ProjectileDamageUp.staticID,
			BuffOnProjectileNegate.staticID
		})
	};

	public new static GameObject Prefab => prefab ?? (prefab = ChaosBundle.Get("Assets/Prefabs/Environment/Destructibles/TreasureChestParty.prefab"));

	public override void Start()
	{
		chestType = TreasureChestType.Party;
		if (opened)
		{
			anim.Play("OpenIdle" + chestType, -1, 0f);
			return;
		}
		anim.Play("Spawning" + chestType, -1, 0f);
		SoundManager.PlayAudioWithDistance("StandardChestSpawn", transform.position);
	}

	public override void Break()
	{
		destroyed = true;
		if (dropLoot)
		{
			spawnLocation = transform.position;
			int num = Random.Range(0, dropSets.Length);
			CalculateVars(dropSets[num].First, isArcanaCheck: true);
			for (int i = 0; i < calcCount; i++)
			{
				Vector3 vector = spawnLocation;
				int amount = 1;
				string skillID = selectedArr[randList[i]];
				bool isEmpowered = Random.value < empChance;
				LootManager.DropSkill(vector, amount, skillID, 0f, 0f, null, useLifeTime: false, isEmpowered);
			}
			CalculateVars(dropSets[num].Second, isArcanaCheck: false);
			for (int j = 0; j < calcCount; j++)
			{
				LootManager.DropItem(spawnLocation, 1, selectedArr[randList[j]]);
			}
			LootManager.DropHealth(spawnLocation, healthDropCount);
			spawnLocation.y += 1.2f;
			PoolManager.GetPoolItem<ConfettiEffect>().EmitSingle(50, spawnLocation);
			SoundManager.PlayAudioWithDistance("StandardChestOpen", spawnLocation);
		}
	}

	private void CalculateVars(string[] givenArr, bool isArcanaCheck)
	{
		if (givenArr == null || givenArr.Length == 0)
		{
			calcCount = -1;
			return;
		}
		selectedArr = givenArr;
		int num = givenArr.Length;
		randList.Clear();
		for (int i = 0; i < num; i++)
		{
			randList.Add(i);
		}
		randList.Shuffle();
		if (isArcanaCheck)
		{
			Player[] activePlayers = GameController.activePlayers;
			foreach (Player player in activePlayers)
			{
				for (int k = 0; k < num; k++)
				{
					if (player.HasSkill(selectedArr[k]))
					{
						randList.Remove(k);
					}
				}
			}
		}
		else
		{
			Player[] activePlayers2 = GameController.activePlayers;
			foreach (Player player2 in activePlayers2)
			{
				for (int m = 0; m < num; m++)
				{
					if (player2.inventory.ContainsItem(selectedArr[m]))
					{
						randList.Remove(m);
					}
				}
			}
		}
		calcCount = Mathf.Min(randList.Count, Random.Range(3, 6));
		droppedCount += calcCount;
		if (droppedCount > maxDropCount)
		{
			calcCount = maxDropCount - droppedCount;
		}
	}
}
