using UnityEngine;

public class Hazard : MonoBehaviour
{
	public enum ActivationType
	{
		Always,
		Timer,
		Trigger,
		Disabled
	}

	public enum ActivationState
	{
		Deactivated,
		Windup,
		Activated
	}

	public enum TimerType
	{
		Local,
		Global,
		GlobalAlt,
		GRapidAlt
	}

	private static ActivationState globalState;

	private static int globalStopwatchID;

	public const float globalDeactivatedTime = 2f;

	public const float globalWindupTime = 1f;

	public const float globalActivatedTime = 2f;

	private static int globalAltCounter;

	private static ActivationState globalAltPri;

	private static ActivationState globalAltSec;

	private static int globalAltStopwatchID;

	public const float globalAltOpen = 0.75f;

	public const float globalAltClosed = 2f;

	private static int gRapidAltCounter;

	private static ActivationState gRapidAltPri;

	private static ActivationState gRapidAltSec;

	public static int gRapidAltStopwatchID;

	public const float gRapidTime = 0.75f;

	protected static string hazardSkillCategory = "EnemyFFA";

	public ActivationType activationType = ActivationType.Disabled;

	public string skillID;

	protected ActivationState currentState;

	protected ActivationState tempState;

	protected bool stateCleared;

	public TimerType timerType;

	public bool isGlobalAltPrimary;

	public float windupTime = 1f;

	public float activatedTime = 2f;

	public float deactivatedTime = 2f;

	protected int instStopwatchID;

	protected Transform atkTrans;

	protected Attack attack;

	protected Collider2D atkCollider;

	protected ChaosQuickStopwatch atkStopwatch = new ChaosQuickStopwatch();

	protected bool atkTimerStarted;

	protected Collider2D activationCollider;

	protected bool hazardTriggered;

	protected bool queueStateChange;

	protected bool AtkColEnabled
	{
		set
		{
			if (atkCollider != null)
			{
				atkCollider.enabled = value;
			}
		}
	}

	protected bool ActivationColEnabled
	{
		set
		{
			if (activationCollider != null)
			{
				activationCollider.enabled = value;
			}
		}
	}

	public static void HandleGlobalTime()
	{
		if (ChaosStopwatch.Check(globalStopwatchID))
		{
			switch (globalState)
			{
			case ActivationState.Deactivated:
				globalStopwatchID = ChaosStopwatch.Begin(1f);
				globalState = ActivationState.Windup;
				break;
			case ActivationState.Windup:
				globalStopwatchID = ChaosStopwatch.Begin(2f);
				globalState = ActivationState.Activated;
				break;
			case ActivationState.Activated:
				globalStopwatchID = ChaosStopwatch.Begin(2f);
				globalState = ActivationState.Deactivated;
				break;
			}
		}
		if (ChaosStopwatch.Check(globalAltStopwatchID))
		{
			switch (globalAltCounter)
			{
			case 0:
				globalAltPri = ActivationState.Windup;
				globalAltSec = ActivationState.Deactivated;
				break;
			case 1:
				globalAltPri = ActivationState.Activated;
				globalAltSec = ActivationState.Deactivated;
				break;
			case 2:
				globalAltPri = ActivationState.Deactivated;
				globalAltSec = ActivationState.Windup;
				break;
			case 3:
				globalAltPri = ActivationState.Deactivated;
				globalAltSec = ActivationState.Activated;
				break;
			}
			globalAltStopwatchID = ChaosStopwatch.Begin((globalAltCounter % 2 != 0) ? 2f : 0.75f);
			globalAltCounter = (globalAltCounter + 1) % 4;
		}
		if (ChaosStopwatch.Check(gRapidAltStopwatchID))
		{
			switch (gRapidAltCounter)
			{
			case 0:
				gRapidAltPri = ActivationState.Windup;
				gRapidAltSec = ActivationState.Activated;
				break;
			case 1:
				gRapidAltPri = ActivationState.Activated;
				gRapidAltSec = ActivationState.Windup;
				break;
			}
			gRapidAltStopwatchID = ChaosStopwatch.Begin(0.75f);
			gRapidAltCounter = (gRapidAltCounter + 1) % 2;
		}
	}

	public virtual void Awake()
	{
		activationCollider = GetComponent<Collider2D>();
		atkTrans = transform.Find("Attack");
		if (atkTrans != null)
		{
			attack = atkTrans.GetComponent<Attack>();
			atkCollider = atkTrans.GetComponent<Collider2D>();
		}
	}

	public virtual void Start()
	{
		Initialize();
	}

	public virtual void Initialize()
	{
		if (attack != null)
		{
			attack.SetAttackInfo(hazardSkillCategory, skillID);
		}
		switch (activationType)
		{
		case ActivationType.Always:
			ActivationColEnabled = false;
			AtkColEnabled = true;
			currentState = ActivationState.Activated;
			OnActivated();
			break;
		case ActivationType.Timer:
			if (timerType == TimerType.Local)
			{
				currentState = ActivationState.Deactivated;
				instStopwatchID = ChaosStopwatch.Begin(deactivatedTime);
			}
			OnDeactivated();
			break;
		case ActivationType.Trigger:
			timerType = TimerType.Local;
			hazardTriggered = false;
			ActivationColEnabled = true;
			AtkColEnabled = false;
			OnDeactivated();
			break;
		case ActivationType.Disabled:
			Disable();
			break;
		}
	}

	public virtual void Disable()
	{
		currentState = ActivationState.Deactivated;
		activationType = ActivationType.Disabled;
		ActivationColEnabled = false;
		AtkColEnabled = false;
		OnDeactivated();
	}

	public virtual void FixedUpdate()
	{
		switch (activationType)
		{
		case ActivationType.Always:
			if (atkTimerStarted)
			{
				if (!atkStopwatch.IsRunning)
				{
					atkTimerStarted = false;
					AtkColEnabled = false;
				}
			}
			else
			{
				atkTimerStarted = true;
				atkStopwatch.IsRunning = true;
				AtkColEnabled = true;
			}
			break;
		case ActivationType.Disabled:
			break;
		default:
			if (queueStateChange)
			{
				queueStateChange = false;
				HandleStateChange(currentState);
			}
			else if (activationType == ActivationType.Timer || hazardTriggered)
			{
				HandleTimer();
			}
			break;
		}
	}

	public virtual void HandleTimer()
	{
		switch (timerType)
		{
		case TimerType.Local:
			if (ChaosStopwatch.Check(instStopwatchID))
			{
				queueStateChange = true;
				switch (currentState)
				{
				case ActivationState.Deactivated:
					currentState = ActivationState.Windup;
					break;
				case ActivationState.Windup:
					currentState = ActivationState.Activated;
					break;
				case ActivationState.Activated:
					currentState = ActivationState.Deactivated;
					break;
				}
			}
			break;
		case TimerType.Global:
			if (!stateCleared)
			{
				if (globalState != ActivationState.Deactivated)
				{
					break;
				}
				stateCleared = true;
			}
			if (currentState != globalState)
			{
				currentState = globalState;
				queueStateChange = true;
			}
			break;
		case TimerType.GlobalAlt:
			tempState = ((!isGlobalAltPrimary) ? globalAltSec : globalAltPri);
			if (!stateCleared)
			{
				if (tempState != ActivationState.Deactivated)
				{
					break;
				}
				stateCleared = true;
			}
			if (currentState != tempState)
			{
				currentState = tempState;
				queueStateChange = true;
			}
			break;
		case TimerType.GRapidAlt:
			tempState = ((!isGlobalAltPrimary) ? gRapidAltSec : gRapidAltPri);
			if (!stateCleared)
			{
				if (tempState != ActivationState.Windup)
				{
					break;
				}
				stateCleared = true;
			}
			if (currentState != tempState)
			{
				currentState = tempState;
				queueStateChange = true;
			}
			break;
		}
	}

	public virtual void HandleStateChange(ActivationState givenState)
	{
		switch (givenState)
		{
		case ActivationState.Deactivated:
			OnDeactivated();
			AtkColEnabled = false;
			if (timerType == TimerType.Local)
			{
				instStopwatchID = ChaosStopwatch.Begin(deactivatedTime);
			}
			hazardTriggered = false;
			ActivationColEnabled = activationType == ActivationType.Trigger;
			break;
		case ActivationState.Windup:
			OnWindup();
			AtkColEnabled = false;
			if (timerType == TimerType.Local)
			{
				instStopwatchID = ChaosStopwatch.Begin(windupTime);
			}
			break;
		case ActivationState.Activated:
			OnActivated();
			AtkColEnabled = true;
			if (timerType == TimerType.Local)
			{
				instStopwatchID = ChaosStopwatch.Begin(activatedTime);
			}
			break;
		}
	}

	public virtual void OnTriggerEnter2D(Collider2D col)
	{
		if (activationType == ActivationType.Trigger && !hazardTriggered && col.name.Contains("FloorContact"))
		{
			hazardTriggered = true;
			queueStateChange = true;
			currentState = ActivationState.Windup;
			ActivationColEnabled = false;
		}
	}

	public virtual void OnWindup()
	{
	}

	public virtual void OnActivated()
	{
	}

	public virtual void OnDeactivated()
	{
	}
}
