		if (transform != null)
		{
			windupEmitter = transform.GetComponent<ParticleSystem>();
		}
	}

	public override void Start()
	{
		base.Start();
		spawnVector = transform.position;
	}

	public override void OnDeactivated()
	{
		if (windupEmitter != null)
		{
			windupEmitter.Stop();
		}
		SetAudioStatus();
	}

	public override void OnWindup()
	{
		attackVector.Normalize();
		calcVector = spawnVector + attackVector * 0.5f;
		if (windupEmitter != null)
		{
			windupEmitter.transform.position = calcVector;
			windupEmitter.Play();
		}
		SetAudioStatus(givenStatus: true);
	}

	public override void OnActivated()
	{
		if (windupEmitter != null)
		{
			windupEmitter.Stop();
		}
		SetAudioStatus();
		currentFW = Globals.ChaosInst<FireWall>(FireWall.Prefab, transform, calcVector);
		currentFW.wavePoolSize = waveCount;
		currentFW.maxWaveCount = waveCount;
		currentFW.spacing = waveSpacing;
		currentFW.destroyDelay = waveDuration;
		currentFW.moveVector = attackVector;
		currentFW.spawnRate = 0.025f;
		currentFW.SetSkillData(Hazard.hazardSkillCategory, skillID);
		currentFW.spawnWaveThroughStopLayermask = true;
		currentFW.stopLayerMask = 0;
		currentFW.ignoreWaveCollisions = true;
	}

	private void SetAudioStatus(bool givenStatus = false, bool isWarmup = false)
	{
		if (burnAudio != null)
		{
			burnAudio.Stop();
			burnAudio = null;
		}
		if (givenStatus)
		{
			burnAudio = SoundManager.PlayIfNotPlaying("FireWallLoop", burnAudio, transform, useStdPitchOverride: false, -1f, 0.15f);
		}
	}
}
using UnityEngine;

public class HazardIce : Hazard
{
	public GameObject snowEmitter;

	public GameObject areaSprite;

	public ParticleSystem windupEmitter;

	private Blizzard currentBL;

	private bool altLevel;

	private ChaosQuickStopwatch recastStopwatch = new ChaosQuickStopwatch(2f);

	private float duration = 2f;

	private int maxHitCount = 8;

	public bool useCastingCircle = true;

	private CastingCircle currentCC;

	private float ccDrawTime = 1f;

	public override void Awake()
	{
		base.Awake();
		switch (timerType)
		{
		case TimerType.Global:
			ccDrawTime = 1f;
			break;
		case TimerType.GlobalAlt:
			ccDrawTime = 0.75f;
			break;
		case TimerType.GRapidAlt:
			ccDrawTime = 0.75f;
			break;
		case TimerType.Local:
			ccDrawTime = windupTime;
			break;
		}
		if (activationType == ActivationType.Trigger)
		{
			ccDrawTime = windupTime;
		}
	}

	public override void OnWindup()
	{
		windupEmitter.Play();
		SetCastingCircleStatus(givenStatus: true);
	}

	public override void OnActivated()
	{
		windupEmitter.Stop();
		CreateBlizzard();
		SetCastingCircleStatus(givenStatus: false);
		SetCastingCircleStatus(givenStatus: true, spinMode: true);
	}

	public override void OnDeactivated()
	{
		windupEmitter.Stop();
		SetCastingCircleStatus(givenStatus: false);
	}

	public override void FixedUpdate()
	{
		if (activationType == ActivationType.Always)
		{
			if (!recastStopwatch.IsRunning)
			{
				recastStopwatch.IsRunning = true;
				CreateBlizzard();
			}
		}
		else
		{
			base.FixedUpdate();
		}
	}

	private void CreateBlizzard()
	{
		altLevel = !altLevel;
		currentBL = Globals.ChaosInst<Blizzard>(Blizzard.Prefab, transform, transform.position);
		currentBL.attackBox.SetAttackInfo(Hazard.hazardSkillCategory, skillID, (!altLevel) ? 1 : 2);
		currentBL.duration = duration;
		currentBL.maxHitCount = maxHitCount;
		currentBL.showCastCircle = false;
	}

	private void SetCastingCircleStatus(bool givenStatus, bool spinMode = false)
	{
		if (useCastingCircle && givenStatus)
		{
			string animName = ((!spinMode) ? "DrawInsideOut" : "Spin");
			Vector3 position = transform.position;
			GameObject parentObj = gameObject;
			Color? color = ((!spinMode) ? CastingCircle.enemyColorDim : CastingCircle.enemyColor);
			float drawTime = ((!spinMode) ? ccDrawTime : 0f);
			currentCC = CastingCirclePool.Spawn(animName, position, disableWithParentVal: true, parentObj, trackParentVal: true, useCastTimeVal: false, 0f, 4f, 0f, color, drawTime);
			currentCC.autoSpinColor = ((!spinMode) ? CastingCircle.enemyColorDim : CastingCircle.enemyColor);
		}
		else if (currentCC != null)
		{
			currentCC.Reset();
		}
	}

	public override void Initialize()
	{
		snowEmitter.SetActive(value: true);
		areaSprite.SetActive(value: true);
		base.Initialize();
	}

	public override void Disable()
	{
		snowEmitter.SetActive(value: false);
		areaSprite.SetActive(value: false);
		base.Disable();
	}
}
