		currentIS.Show();
		ChaosStopwatch.Pause(currentIS.flyStopwatchID);
		altSkillLevel = !altSkillLevel;
	}

	public override void OnActivated()
	{
		if (!(currentIS == null))
		{
			ChaosStopwatch.Resume(currentIS.flyStopwatchID);
