			currentIS.moveSpeed = attackSpeed;
			currentIS.flyTime = attackRange / attackSpeed;
			currentIS.RefreshFlightTime();
			currentIS = null;
		}
	}

	public override void OnDeactivated()
	{
		if (currentIS != null)
		{
			currentIS.ResetProjectile();
		}
	}
