using System.Collections.Generic;
using Chaos.ListExtensions;
using UnityEngine;
public class KnockbackWall : Destructible
{
	public class KnockbackWallHurtState : DestructibleHurtState
	{
		private AttackInfo incomingAttack;
		public new KnockbackWall parent;
		public KnockbackWallHurtState(string stateName, FSM parentFSM, KnockbackWall parentEntity)
			: base(stateName, parentFSM, parentEntity)
		{
			parent = parentEntity;
		}
		public override void OnEnter()
		{
			if (!parent.IsRooted && parent.health.lastAttack != null)
			{
				incomingAttack = parent.health.lastAttack;
				if (incomingAttack.skillID == skillID && !parent.IgnoreWallToWallCollisions)
				{
					fsm.ChangeState("Dead");
					return;
				}
				parent.movement.EndMovement();
				parent.WallStruck(incomingAttack.knockbackVector, incomingAttack.skillCategory, incomingAttack.damage, incomingAttack.knockbackMultiplier);
			}
		}
	}
	private ChaosQuickStopwatch emitTimer;
	private static float emitInterval = 0.008f;
	private static GameObject prefab;
	private string currentSkillCategory = "EnemyScaled";
	private string currentSkillID = "KnockbackWall";
	public static string skillID = "KnockbackWall";
	private static string explosionSkillID = "EarthExplosion";
	public static List<KnockbackWall> knockbackWallList;
	private static float closestDist;
	private static float currentDist;
	private static KnockbackWall closestWall;
	public float lifeTime = 20f;
	[HideInInspector]
	public int lifeStopwatchID;
	public float rootTime = 2f;
	private int rootStopwatchID;
	private bool isMoving;
	private bool isRooted;
	private SpriteRenderer rootSprite;
	private SpriteRenderer wallSprite;
	private const float minForce = 100f;
	private const float maxForce = 1000f;
	private const float defaultForce = 100f;
	private float minMagnitudeForDmg = 1f;
	private float initMagnitude = 1f;
	private float currentMagnitude;
	private float initDamage;
	[HideInInspector]
	public float castTime = 0.5f;
	private int castStopwatchID;
	private bool summoned;
	private bool removedFromList;
	public bool showCastingCircle = true;
	public bool ignoreWallToWallCollisions;
	public bool spawnExplosionOnDestroy;
	public bool destroyOnImpact = true;
	private bool explosionSpawned;
	private bool wallClaimed;
	private float claimDuration = 1.5f;
	public static GameObject Prefab => prefab ?? (prefab = ChaosBundle.Get("Assets/Prefabs/Environment/Destructibles/KnockbackWall.prefab"));
	public bool IsRooted
	{
		get
		{
			return isRooted;
		}
		set
		{
			isRooted = value;
			rigidbody2D.isKinematic = value;
		}
	}
	public bool IgnoreWallToWallCollisions
	{
		get
		{
			return ignoreWallToWallCollisions;
		}
		set
		{
			ignoreWallToWallCollisions = value;
			currentSkillID = ((!ignoreWallToWallCollisions) ? skillID : "KnockbackWallTargetOnly");
		}
	}
	public static KnockbackWall GetClosestWall(Vector3 position, float range)
	{
		if (knockbackWallList == null || range <= 0f)
		{
			return null;
		}
		closestDist = 9999f;
		currentDist = 0f;
		closestWall = null;
		knockbackWallList.RemoveNullValues();
		foreach (KnockbackWall knockbackWall in knockbackWallList)
		{
			if (!knockbackWall.wallClaimed)
			{
				currentDist = Vector2.Distance(position, knockbackWall.transform.position);
				if (currentDist <= range && currentDist < closestDist)
				{
					closestDist = currentDist;
					closestWall = knockbackWall;
				}
			}
		}
		if (closestWall == null)
		{
			return null;
		}
		closestWall.ClaimWall();
		return closestWall;
	}
	public override void Awake()
	{
		if (knockbackWallList == null)
		{
			knockbackWallList = new List<KnockbackWall>();
		}
		base.Awake();
		isMoving = false;
		rootSprite = transform.Find("RootSprite").GetComponent<SpriteRenderer>();
		wallSprite = transform.Find("WallSprite").GetComponent<SpriteRenderer>();
		rootSprite.enabled = false;
		wallSprite.enabled = false;
		shadowSprite.enabled = false;
		hurtBoxCollider.enabled = false;
		floorContact.SetActive(value: false);
		Attack attack = base.attack;
		attack.attackCollisionEventHandlers = (Attack.AttackCollisionEventHandler)Delegate.Combine(attack.attackCollisionEventHandlers, new Attack.AttackCollisionEventHandler(OnImpact));
	}
	public override void Start()
	{
		base.Start();
		lifeStopwatchID = ChaosStopwatch.Begin(lifeTime);
		rootStopwatchID = ChaosStopwatch.Begin(rootTime);
		castStopwatchID = ChaosStopwatch.Begin(castTime);
		emitTimer = new ChaosQuickStopwatch(emitInterval);
		IgnoreWallToWallCollisions = ignoreWallToWallCollisions;
		SoundManager.PlayAudioWithDistance("EarthCrumble", transform.position);
		attack.collider.enabled = false;
		summoned = false;
		removedFromList = false;
	}
	public override void InitFSM()
	{
		fsm = new FSM();
		fsm.defaultStateName = "Idle";
		fsm.AddState(new DestructibleIdleState("Idle", fsm, this));
		fsm.AddState(new DestructibleDeadState("Dead", fsm, this));
		fsm.AddState(new KnockbackWallHurtState("Hurt", fsm, this));
		fsm.ChangeState(fsm.defaultStateName);
	}
	public override void Update()
	{
		if (isMoving && fsm.currentStateName != "Dead" && !emitTimer.IsRunning)
		{
			PoolManager.GetPoolItem<FloorCrackEmitter>().Emit(1, transform.position);
			emitTimer.IsRunning = true;
		}
		if (!summoned)
		{
			if (ChaosStopwatch.Check(castStopwatchID))
			{
				knockbackWallList.Add(this);
				summoned = true;
				IsRooted = true;
				SoundManager.PlayAudioWithDistance("ExplosionShort", transform.position);
				if (UnityEngine.Random.value > 0.5f)
				{
					wallSprite.transform.localScale = new Vector3(0f - wallSprite.transform.localScale.x, wallSprite.transform.localScale.y, wallSprite.transform.localScale.z);
				}
				wallSprite.enabled = true;
				shadowSprite.enabled = true;
				hurtBoxCollider.enabled = true;
				floorContact.SetActive(value: true);
				PoolManager.GetPoolItem<RockDebrisEmitter>().EmitSingle(2, transform.position + new Vector3(0f, 0.5f, 0f));
				PoolManager.GetPoolItem<FloorCrackEmitter>().Emit(1, transform.position);
			}
			return;
		}
		if (IsRooted && ChaosStopwatch.Check(rootStopwatchID))
		{
			IsRooted = false;
		}
		base.Update();
		HandleDecay();
		if (!destroyed && ChaosStopwatch.Check(lifeStopwatchID) && !fsm.currentStateName.Contains("Fall"))
		{
			fsm.ChangeState("Dead");
			if (spawnExplosionOnDestroy && !explosionSpawned)
			{
				explosionSpawned = true;
				EarthBurst.CreateBurst(transform.position, currentSkillCategory, skillID, 1, 2.5f);
			}
		}
	}
	private void HandleDecay()
	{
		if (!removedFromList && ChaosStopwatch.GetRemainingTime(lifeStopwatchID) < 1f)
		{
			removedFromList = true;
			knockbackWallList.Remove(this);
		}
		if (!isMoving)
		{
			attack.collider.enabled = false;
			return;
		}
		currentMagnitude = rigidbody2D.velocity.magnitude;
		isMoving = currentMagnitude > minMagnitudeForDmg;
		if (!emitTimer.IsRunning)
		{
			DustEmitter poolItem = PoolManager.GetPoolItem<DustEmitter>();
			int num = 3;
			float z = Globals.GetRotationVector(-movement.moveVector).z;
			float startSpeed = 1f;
			float startSize = 1.25f;
			Vector3? emitPosition = transform.position;
			poolItem.EmitDirBurst(num, z, startSpeed, startSize, -1f, emitPosition);
		}
		if (initMagnitude > 0f)
		{
			attack.damageOverride = Mathf.CeilToInt(initDamage * currentMagnitude / initMagnitude);
			attack.knockbackMultiplierOverride = attack.damageOverride;
		}
	}
	public void ClaimWall()
	{
		StartCoroutine(HandleClaimDuration());
	}
	public IEnumerator HandleClaimDuration()
	{
		int claimStopwatchID = ChaosStopwatch.Begin(claimDuration);
		wallClaimed = true;
		while (wallClaimed && !ChaosStopwatch.Check(claimStopwatchID))
		{
			yield return null;
		}

