using UnityEngine;
public class Blockcade : WoodDestructible
{
	public class BlockcadeDeadState : DestructibleDeadState
	{
		public new Blockcade parent;
		public BlockcadeDeadState(string newName, FSM newFSM, Blockcade newEnt)
			: base(newName, newFSM, newEnt)
		{
			parent = newEnt;
		}
		public override void OnEnter()
		{
			parent.Break();
			if (parent.breakAsGroup)
			{
				parent.ClearBlockGroup();
			}
			if (parent.autoDestroyOnDeath && parent.gameObject != null)
			{
				Object.Destroy(parent.gameObject, parent.autoDestroyDelay);
			}
		}
	}
	public bool breakAsGroup;
	public bool ignoreActivation;
	public bool autoResetActivation;
	private GameObject activationObj;
	private bool isActivated;
	public override void InitComponents()
	{
		base.InitComponents();
		activationObj = transform.Find("ActivationCollider").gameObject;
		if (ignoreActivation)
		{
			activationObj.SetActive(value: false);
		}
	}
	public override void InitFSM()
	{
		fsm = new FSM();
		fsm.defaultStateName = "Idle";
		fsm.AddState(new DestructibleIdleState("Idle", fsm, this));
		fsm.AddState(new BlockcadeDeadState("Dead", fsm, this));
		fsm.ChangeState(fsm.defaultStateName);
	}
	public override void Break()
	{
		if (!destroyed)
		{
			destroyed = true;
			GameController.enemies.Remove(gameObject);
			GameController.allies.Remove(gameObject);
			base.Break();
		}
	}
	private void SetAvailableStatus(bool givenStatus)
	{
		if (givenStatus)
		{
			if (!GameController.allies.Contains(gameObject))
			{
				GameController.allies.Add(gameObject);
			}
			Enemy.AddEnemy(gameObject);
		}
		else
		{
			GameController.enemies.Remove(gameObject);
			GameController.allies.Remove(gameObject);
		}
	}
	public override void OnTriggerEnter2D(Collider2D col)
	{
		if (!ignoreActivation && !isActivated && ColliderIsPlayer(col))
		{
			isActivated = true;
			if (!autoResetActivation && activationObj != null)
			{
				activationObj.SetActive(value: false);
			}
			SetAvailableStatus(givenStatus: true);
		}
	}
	public void OnTriggerExit2D(Collider2D col)
	{
		if (autoResetActivation && !ignoreActivation && isActivated && ColliderIsPlayer(col))
		{
			isActivated = false;
			SetAvailableStatus(givenStatus: false);
		}
	}
	private bool ColliderIsPlayer(Collider2D col)
	{
		return col != null && ((1 << col.gameObject.layer) & ChaosCollisions.layerPlayer) != 0;
	}
	private new void Reset()
	{
		if (!destroyed)
		{
			fsm.ChangeState("Dead");
		}
	}
	private void ClearBlockGroup()
	{
		Blockcade[] componentsInChildren = transform.parent.GetComponentsInChildren<Blockcade>();
		foreach (Blockcade blockcade in componentsInChildren)
		{
			if (blockcade != null && blockcade != this)
			{
				blockcade.Reset();
			}
		}
	}
}
