[AddComponentMenu("Chaos/Components/Fall")]
public class Fall : ComponentBase
{
	public GameObject floorContact;
	public Collider2D fallCol;
	public bool centerFall;
	public bool disableFallTransition;
	public static float minSqrVelocityToNotFall = 400f;
	public Vector3 preFallPos;
	private bool isReady;
	private Collider2D[] pointHits = new Collider2D[10];
	public BoolVarStat ignoreFall;
	private bool ignoreFallStarted;
	private int ignoreFallStopwatchID;
	private float ignoreFallDuration = 2f;
	public PlayerHUD playerHUD;
	public bool hasIgnorePitsItem;
	private bool IsAirborne => entityScript != null && entityScript.airborneStat.CurrentValue;
	public override void Start()
	{
		base.Start();
		bool flag = true;
		if (entityScript != null && entityScript.disablePreventFallCollider)
		{
			flag = false;
		}
		int childCount = transform.childCount;
		for (int i = 0; i < childCount; i++)
		{
			GameObject gameObject = transform.GetChild(i).gameObject;
			if (flag)
			{
				if (gameObject.name.ToLower().Contains("preventfall"))
				{
					floorContact = gameObject;
					break;
				}
			}
			else if (gameObject.name.ToLower().Contains("floorcontact"))
			{
				floorContact = gameObject;
				break;
			}
		}
		if (floorContact != null)
		{
			base.Start();
			fallCol = floorContact.GetComponent<Collider2D>();
		}
		isReady = !(floorContact == null) && !(fallCol == null) && parentFSM != null;
	}
	private void Update()
	{
		if (!isReady)
		{
			enabled = false;
		}
		else
		{
			if (disableFallTransition || IsAirborne || parentFSM.currentStateName.Contains("Fall") || parentFSM.currentStateName.Contains("Dead") || rigidbody2D.velocity.sqrMagnitude >= minSqrVelocityToNotFall)
			{
				return;
			}
			if (!CheckOnPit())
			{
				preFallPos = transform.position;
				if (ignoreFallStarted)
				{
					ignoreFallStarted = false;
					if (playerHUD != null && playerHUD.castBar != null)
					{
						playerHUD.castBar.EndCast();
					}
				}
				return;
			}
			if (ignoreFall.CurrentValue)
			{
				if (!hasIgnorePitsItem)
				{
					return;
				}
				PoolManager.GetPoolItem<AirWalkEmitter>().EmitSingle(1, new Vector3(entityScript.lastTileCol, -entityScript.lastTileRow));
				if (!ignoreFallStarted)
				{
					ignoreFallStarted = true;
					ignoreFallStopwatchID = ChaosStopwatch.Begin(ignoreFallDuration);
					if (playerHUD != null && playerHUD.castBar != null)
					{
						playerHUD.castBar.StartCast(ignoreFallStopwatchID, givenStatus: false);
					}
					return;
				}
				if (!ChaosStopwatch.Check(ignoreFallStopwatchID))
				{
					return;
				}
				ignoreFallStarted = false;
				if (playerHUD != null && playerHUD.castBar != null)
				{
					playerHUD.castBar.EndCast();
				}
			}
			TransitionToFall();
		}
	}
	public bool CheckOnPit()
	{
		return fallCol != null && Physics2D.OverlapPointNonAlloc(fallCol.bounds.center, pointHits, ChaosCollisions.layerPit) > 0;
	}
	public bool CheckForFall()
	{
		return isReady && !disableFallTransition && !ignoreFall.CurrentValue && CheckOnPit();
	}
	public void TransitionToFall()
	{
		if (parentFSM.HasState("Fall"))
		{
			parentFSM.QueueChangeState("Fall");
		}
	}
}
