using UnityEngine;
public static class PitGenerator
{
	public static void GeneratePits(TileGrid tileGrid, Transform parentTrans = null)
	{
		GameObject gameObject = Globals.FindOrCreateGameObject("Colliders", parentTrans);
		parentTrans = gameObject.transform;
		GameObject gameObject2 = Globals.FindOrCreateGameObject("PitColliders", parentTrans);
		if (parentTrans != null)
		{
			gameObject2.transform.position = parentTrans.position;
			gameObject2.transform.SetParent(parentTrans);
		}
		gameObject2.tag = "BottomlessPit";
		gameObject2.layer = LayerMask.NameToLayer("Pit");
		gameObject2.transform.position = new Vector3(gameObject2.transform.position.x, gameObject2.transform.position.y, 2f);
		Collider2D[] components = gameObject2.GetComponents<Collider2D>();
		foreach (Collider2D obj in components)
		{
			Object.DestroyImmediate(obj);
		}
		PolygonCollider2D polygonCollider2D = gameObject2.AddComponent<PolygonCollider2D>();
		polygonCollider2D.isTrigger = true;
		List<List<IntPoint>> list = new List<List<IntPoint>>();
		for (int j = 0; j < tileGrid.RowCount; j++)
		{
			for (int k = 0; k < tileGrid.ColCount; k++)
			{
				Tile tile = tileGrid[j, k];
				if (tile != null && tile.terrain == Tile.TerrainType.Pit)
				{
					List<IntPoint> list2 = new List<IntPoint>();
					list2.Add(new IntPoint(tile.vertices[0].x, tile.vertices[0].y));
					list2.Add(new IntPoint(tile.vertices[1].x, tile.vertices[1].y));
					list2.Add(new IntPoint(tile.vertices[3].x, tile.vertices[3].y));
					list2.Add(new IntPoint(tile.vertices[2].x, tile.vertices[2].y));
					list.Add(list2);
				}
			}
		}
		list = Clipper.SimplifyPolygons(list);
		List<List<Vector2>> list3 = new List<List<Vector2>>();
		foreach (List<IntPoint> item2 in list)
		{
			List<Vector2> list4 = new List<Vector2>();
			for (int l = 0; l < item2.Count; l++)
			{
				Vector2 item = new Vector2(item2[l].X, item2[l].Y);
				list4.Add(item);
			}
			list3.Add(list4);
		}
		polygonCollider2D.pathCount = list3.Count;
		for (int m = 0; m < list3.Count; m++)
		{
			polygonCollider2D.SetPath(m, list3[m].ToArray());
		}
		gameObject2.transform.DestroyChildren(destroyImmediate: true, string.Empty);
		GameObject gameObject3 = Object.Instantiate(gameObject2, gameObject2.transform.position, Quaternion.identity);
		gameObject3.transform.SetParent(gameObject2.transform);
		gameObject3.transform.localPosition = Vector3.zero;
		gameObject3.transform.name = "PreventFallPitCollider";
		gameObject3.layer = LayerMask.NameToLayer("PreventFallPitCollider");
		Collider2D[] components2 = gameObject3.GetComponents<Collider2D>();
		foreach (Collider2D collider2D in components2)
		{
			collider2D.isTrigger = false;
		}
	}
}
