	{
		Player[] activePlayers = GameController.activePlayers;
		foreach (Player player in activePlayers)
		{
			if (player != null && !player.IsAvailable)
			{
				yield break;
			}
		}
		GameUI.dialogManager.Deactivate(resetDialog: true);
		SoundManager.PlayAudio("Portal");
		GameController.loadingScreen.Enable();
		GameController.loadingScreen.SetPromptText(string.Empty);
		if (targetSpawnOffset == Vector3.zero)
		{
			targetSpawnOffset = Vector3.down;
		}
		Player[] activePlayers2 = GameController.activePlayers;
		foreach (Player player2 in activePlayers2)
		{
			if (!(player2 == null) && !player2.IsDead)
			{
				player2.transform.position = targetLocation + targetSpawnOffset;
				player2.FaceTarget(player2.transform.position + Vector3.down);
				player2.Hide();
			}
		}
		GameController.PauseAllPlayers();
		GameController.loadingScreen.queueDisableOnly = true;
		GameController.loadingScreen.FadeOut();
		if (useLocLog)
		{
			PortalManager.SetLastPortal(this, transform.position);
		}
		yield return waitForFadeout;
		PoolManager.GetPoolItem<SpawnPortal>().Spawn(targetLocation + targetSpawnOffset, color);
		yield return waitForSpawnIn;
		Player[] activePlayers3 = GameController.activePlayers;
		foreach (Player player3 in activePlayers3)
		{
			player3.Show();
		}
		GameController.PauseAllPlayers(state: false);
	}
