using System.Collections.Generic;
using UnityEngine;
public class PortalManager
{
	public static Color itemColor = Color.green;
	public static Color skillColor = Color.magenta;
	public static Color miscColor = new Color(0.6f, 0f, 0f, 1f);
	public static Color startColor = Color.cyan;
	public static Vector2 exitOffset = Vector2.down * 1.5f;
	private static Vector2 lastPosition;
	private static Portal lastPortal;
	private static Dictionary<Portal.PortalType, Portal> portDict = new Dictionary<Portal.PortalType, Portal>();
	private static Portal redirPortal;
	private static Portal currentPortal;
	public static void SetLastPortal(Portal givenPortal, Vector2 givenPosition)
	{
		lastPortal = givenPortal;
		lastPosition = givenPosition;
		if (!(givenPortal == redirPortal))
		{
			if (redirPortal == null)
			{
				redirPortal = CreatePortal(Level.startPosition, lastPosition + exitOffset, lastPortal.color);
				return;
			}
			redirPortal.targetLocation = lastPosition;
			redirPortal.InitColor(lastPortal.color);
		}
	}
	public static void CreateDirectedPortal(Portal.PortalType givenType)
	{
		if (!Level.exitFound && NextLevelLoader.InTierScene(string.Empty))
		{
			Vector2 vector = Vector2.zero;
			Color white = Color.white;
			switch (givenType)
			{
			case Portal.PortalType.Item:
				vector = Level.itemStorePortalOutPosition;
				white = itemColor;
				break;
			case Portal.PortalType.Skill:
				vector = Level.skillStorePortalOutPosition;
				white = skillColor;
				break;
			case Portal.PortalType.Misc:
				vector = Level.miscRoomPortalOutPosition;
				white = miscColor;
				break;
			}
			portDict[givenType] = CreatePortal(vector, Level.startPosition, white);
			SetLastPortal(portDict[givenType], vector);
		}
	}
	private static Portal CreatePortal(Vector2 givenSpawn, Vector2 givenTarget, Color givenColor)
	{
		currentPortal = Globals.ChaosInst<Portal>(Portal.Prefab, null, givenSpawn);
		currentPortal.targetLocation = givenTarget;
		currentPortal.targetSpawnOffset = exitOffset;
		currentPortal.color = givenColor;
		currentPortal.createReturnPortal = false;
		currentPortal.useLocLog = true;
		return currentPortal;
	}
	public static void ResetDirectedPortals()
	{
		if (redirPortal != null)
		{
			redirPortal.SetPortalStatus(givenStatus: false);
		}
		foreach (Portal value in portDict.Values)
		{
			if (value != null)
			{
				value.SetPortalStatus(givenStatus: false);
			}
		}
	}
}
using UnityEngine;
public class ExitPortal : MonoBehaviour
{
	[HideInInspector]
	public Animator anim;
	[HideInInspector]
	public NextLevelLoader nextLevelLoader;
	private Animator arcanaAnim;
	private AnimEffect tpAnimEffect;
	private bool tpStarted;
	private bool tpStartedSkippedFrame;
	private bool playersHidden;
	public static float tpEffectHideTime = 0.1f;
	public bool queueEndGameSummary;
	public bool disableMiniArcana;
	public bool hideArcanaOnSpawn;
	private AudioSource prepareAudio;
	public void Awake()
	{
		anim = GetComponent<Animator>();
		if (!disableMiniArcana)
		{
			GameObject gameObject = Object.Instantiate(ChaosBundle.Get("Assets/Prefabs/Items/ArcanaMini.prefab"), Vector3.zero, Quaternion.identity, transform);
			gameObject.transform.localPosition = new Vector3(0f, 1.0625f, 0f);
			arcanaAnim = gameObject.GetComponent<Animator>();
			if (hideArcanaOnSpawn)
			{
				arcanaAnim.Play("Hidden");
			}
		}
	}
	public void Start()
	{
		nextLevelLoader = transform.Find("NextLevelTrigger").GetComponent<NextLevelLoader>();
		nextLevelLoader.showLevelSummary &= !Level.isBossRushMode;
		Globals.AddItemRepeller(nextLevelLoader.gameObject, 2f, "ItemRepeller");
	}
	public void Update()
	{
		if (tpStarted && !tpStartedSkippedFrame)
		{
			tpStartedSkippedFrame = true;
		}
		else
		{
			if (!tpStarted)
			{
				return;
			}
			float animTime = tpAnimEffect.GetAnimTime();
			if (!playersHidden && (animTime >= tpEffectHideTime || !tpAnimEffect.playing))
			{
				Player[] activePlayers = GameController.activePlayers;
				foreach (Player player in activePlayers)
				{
					if (player != null)
					{
						player.Hide();
					}
				}
				playersHidden = true;
			}
			else if (animTime >= 1f || !tpAnimEffect.playing)
			{
				tpStarted = false;
				LoadNextLevel();
			}
		}
	}
	public virtual void Close()
	{
		tpStarted = true;
		GameController.PauseAllPlayers();
		GameController.allies.Clear();
		DustEmitter poolItem = PoolManager.GetPoolItem<DustEmitter>();
		int particleCount = 200;
		Vector3? emitPosition = transform.position;
		poolItem.EmitCircle(particleCount, 1f, -1f, -1f, emitPosition);
		anim.Play("Teleport", -1, 0f);
		tpAnimEffect = PoolManager.GetPoolItem<AnimEffect>("TeleportEffect");
		tpAnimEffect.Play(transform.position, string.Empty);
	}
	public void LoadNextLevel()
	{
		if (queueEndGameSummary)
		{
			GameUI.deathSummary.Activate();
		}
		else
		{
			nextLevelLoader.LoadNextLevel();
		}
	}
	public void Prepare()
	{
		anim.Play("Prepare");
		if (!disableMiniArcana)
		{
			arcanaAnim.Play("Spin", -1, 0f);
		}
		prepareAudio = SoundManager.PlayIfNotPlaying("PortalShine", prepareAudio, transform, useStdPitchOverride: false);
	}
	public void Deactivate()
	{
		if (!tpStarted)
		{
			anim.Play("Deactivate", -1, 0f);
			if (!disableMiniArcana)
			{
				arcanaAnim.Play("Idle", -1, 0f);
			}
			if (prepareAudio != null)
			{
				prepareAudio.Stop();
				prepareAudio = null;
			}
		}
	}
}
