	}

using System.Collections;
using UnityEngine;
public class RandomDisasters : Item
{
	public static string staticID = "RandomDisasters";
	private bool disasterRunning;
	private ChaosQuickStopwatch disasterStopwatch;
	private Vector2 parentPosition;
	private CastingCircle currentCircle;
	private static readonly string meteorID = "RandomDisastersMeteor";
	private MeteorStrike currentMS;
	private static readonly string pressureID = "RandomDisastersPressure";
	private PressureWave currentPW;
	private static readonly string boulderID = "RandomDisastersBoulder";
	private BoulderDrop currentBD;
	private static readonly string thunderID = "RandomDisastersThunder";
	private ThunderBlast currentTB;
	private static readonly string blizzardID = "RandomDisastersBlizzard";
	private Blizzard currentBL;
	private NumVarStatMod blizMoveMod;
	private float CooldownDelay => Random.Range(2.5f, 4f);
	private bool DiasterAllowed => !LoadingScreen.loading && NextLevelLoader.InTierScene(string.Empty);
	public RandomDisasters()
	{
		ID = staticID;
		category = Category.Misc;
		isCursed = true;
		hubOnly = true;
		disasterStopwatch = new ChaosQuickStopwatch();
		blizMoveMod = new NumVarStatMod(ID, 6f, 10, VarStatModType.Override);
	}
	public override void Activate()
	{
		if (!(parentEntity == null))
		{
			disasterRunning = true;
			parentEntity.StartCoroutine(SpawnDisasters());
		}
	}
	public override void Deactivate()
	{
		disasterRunning = false;
	}
	private IEnumerator SpawnDisasters()
	{
		WaitWhile waitWhileStopwatch = new WaitWhile(() => disasterStopwatch.IsRunning);
		while (disasterRunning)
		{
			yield return waitWhileStopwatch;
			disasterStopwatch.SetDelay(CooldownDelay, stopCurrent: false, autoStart: true);
			if (DiasterAllowed)
			{
				SpawnDisaster();
			}
			yield return null;
		}
	}
	private void SpawnDisaster()
	{
		if (parentEntity == null)
		{
			disasterRunning = false;
			return;
		}
		parentPosition = CameraController.V2Position;
		switch (Random.Range(0, 5))
		{
		case 0:
			parentEntity.StartCoroutine(SpawnBlizzard(parentPosition));
			break;
		case 1:
			parentEntity.StartCoroutine(SpawnBoulderDrop(parentPosition));
			parentEntity.StartCoroutine(SpawnBoulderDrop(parentPosition, 0.25f));
			if (Globals.RandBool)
			{
				parentEntity.StartCoroutine(SpawnBoulderDrop(parentPosition, 0.75f));
			}
			break;
		case 2:
			parentEntity.StartCoroutine(SpawnMeteor(parentPosition));
			if (Globals.RandBool)
			{
				parentEntity.StartCoroutine(SpawnMeteor(parentPosition, 0.75f));
			}
			break;
		case 3:
			parentEntity.StartCoroutine(SpawnPressureWave(parentPosition));
			if (Globals.RandBool)
			{
				parentEntity.StartCoroutine(SpawnPressureWave(parentPosition, 1f));
			}
			break;
		default:
			SpawnThunderBlast(parentPosition);
			break;
		}
	}
	private IEnumerator SpawnMeteor(Vector2 givenPosition, float givenDelay = 0f)
	{
		if (givenDelay > 0f)
		{
			yield return new WaitForSeconds(givenDelay);
		}
		givenPosition += new Vector2(Random.Range(-10f, 10f), Random.Range(-6f, 6f));
		currentMS = PoolManager.GetPoolItem<MeteorStrike>();
		currentMS.Initialize(givenPosition, useCast: true, useEnemyColor: true);
		currentMS.attack.SetAttackInfo(Enemy.globalEnemySkillCategory, meteorID);
		currentMS.anim.speed = Random.Range(1f, 2f);
		currentMS.shakeIntensity = 0.1f;
	}
	private IEnumerator SpawnBlizzard(Vector2 givenPosition)
	{
		Vector2 spawnVec = givenPosition + new Vector2(Random.Range(8f, 10f) * ((!Globals.RandBool) ? (-1f) : 1f), Random.Range(4f, 6f) * ((!Globals.RandBool) ? (-1f) : 1f));
		currentCircle = CastingCirclePool.Spawn("Draw", spawnVec, disableWithParentVal: false, null, trackParentVal: true, useCastTimeVal: true, 4.75f, 0f, 0f, CastingCircle.enemyColor, 0.75f);
		yield return Globals.waitForThreeQts;
		currentBL = Globals.ChaosInst<Blizzard>(Blizzard.Prefab, null, spawnVec);
		currentBL.attackBox.SetAttackInfo(Enemy.globalEnemySkillCategory, blizzardID);
		currentBL.maxHitCount = 16;
		currentBL.duration = 4f;
		currentBL.useMovement = true;
		currentBL.movement.moveSpeedStat.AddMod(blizMoveMod);
		currentBL.movement.moveVector = (givenPosition + Random.insideUnitCircle * 3f - spawnVec).normalized;
		currentBL.castingCircle = currentCircle;
