public class EnemyTurret : Enemy
{
	public class TurretIdleState : IdleState
	{
		public new EnemyTurret parent;
		public TurretIdleState(string newName, FSM newFSM, EnemyTurret newEnt)
			: base(newName, newFSM, newEnt)
		{
			parent = newEnt;
		}
		public override void Update()
		{
			EnemyTurret enemyTurret = parent;
			List<GameObject> targetGroup = parent.targetGroup;
			Vector3 position = parent.transform.position;
			float attackRadius = parent.attackRadius;
			int lineOfSightLayerMask = parent.lineOfSightLayerMask;
			enemyTurret.closestTargetInfo = Entity.GetClosestTarget(targetGroup, position, attackRadius, playerTagOnly: false, null, null, requireLOS: true, lineOfSightLayerMask);
			if (parent.closestTargetInfo != null)
			{
				parent.turretIris.localPosition = (parent.closestTargetInfo.hurtBoxPosition - parent.turretEyeInner.position).normalized * parent.eyeOffsetMultipler;
			}
			if (ChaosStopwatch.Check(parent.attackCDStopwatchID))
			{
				base.Update();
			}
		}
	}
	public class TurretAttackState : State<EnemyTurret>
	{
		public float attackWarningTime;
		public float shotDelay;
		public int barrageCount;
		private int attackWarningStopwatchID;
		private int shotDelayStopwatchID;
		private Vector2 shootVector;
		private TargetInfo lastValidTargetInfo;
		private bool useLastValidTargetInfo;
		private bool barrageTimerStarted;
		private GameObject projectilePrefab;
		private bool atkCDReady;
		public TurretAttackState(string newName, FSM newFSM, EnemyTurret newEnt)
			: base(newName, newFSM, newEnt)
		{
			projectilePrefab = ChaosBundle.Get("Assets/Prefabs/Projectiles/EnemyFireball.prefab");
			attackWarningTime = 0.75f;
			shotDelay = 0.25f;
			barrageCount = 1;
		}
		private void AttackPrep()
		{
			attackWarningStopwatchID = ChaosStopwatch.Begin(attackWarningTime);
			parent.anim.Play("Alert");
			lastValidTargetInfo = null;
			useLastValidTargetInfo = false;
			barrageTimerStarted = false;
		}
		public override void OnEnter()
		{
			atkCDReady = ChaosStopwatch.Check(parent.attackCDStopwatchID);
			if (atkCDReady)
			{
				AttackPrep();
			}
		}
		public override void Update()
		{
			if (!atkCDReady)
			{
				if (parent.UpdateTargetInfo(parent.attackRadius, reqLOS: true) == null)
				{
					fsm.ChangeState(fsm.defaultStateName);
				}
				atkCDReady = ChaosStopwatch.Check(parent.attackCDStopwatchID);
				if (atkCDReady)
				{
					AttackPrep();
				}
				return;
			}
			parent.UpdateTargetInfo(parent.attackRadius, reqLOS: true);
			if (parent.closestTargetInfo == null || parent.closestTargetInfo.hurtBoxTransform == null)
			{
				if (lastValidTargetInfo == null || lastValidTargetInfo.hurtBoxTransform == null)
				{
					parent.fsm.ChangeState(fsm.defaultStateName);
					return;
				}
				useLastValidTargetInfo = true;
			}
			else
			{
				useLastValidTargetInfo = false;
				lastValidTargetInfo = parent.closestTargetInfo;
			}
			shootVector = (((!useLastValidTargetInfo) ? parent.closestTargetInfo.hurtBoxPosition : lastValidTargetInfo.hurtBoxPosition) - parent.turretEyeInner.position).normalized;
			parent.turretIris.localPosition = shootVector * parent.eyeOffsetMultipler;
			if (ChaosStopwatch.Check(attackWarningStopwatchID))
			{
				if (!barrageTimerStarted)
				{
					barrageTimerStarted = true;
					shotDelayStopwatchID = ChaosStopwatch.Begin(0f, useInterval: true, shotDelay, barrageCount);
				}
				switch (ChaosStopwatch.CheckInterval(shotDelayStopwatchID))
				{
				case StopwatchState.Ready:
				{
					Projectile projectile = CreateProjectile();
					projectile.moveVector = shootVector;
					projectile.attackBox.collider.enabled = true;
					parent.anim.Play("Attack");
					SoundManager.PlayAudioWithDistance(parent.attackAudioID, parent.transform.position);
					SoundManager.PlayAudioWithDistance("MageFireballForm", parent.transform.position);
					break;
				}
				case StopwatchState.Done:
					parent.fsm.ChangeState(fsm.defaultStateName);
					break;
				}
			}
		}
		public override void OnExit()
		{
			base.OnExit();
			parent.attackCDStopwatchID = ChaosStopwatch.Begin(parent.attackCDTime);
		}
		private Projectile CreateProjectile()
		{
			Projectile component = Object.Instantiate(projectilePrefab, parent.turretIris.position, Quaternion.identity).GetComponent<Projectile>();
			component.parentObject = parent.gameObject;
			component.attackBox.SetAttackInfo(parent.skillCategory, "NeutralTurretFireball");
			component.projectileSpriteRenderer.enabled = true;
			component.projectileSpriteRenderer.material.SetFloat("_PaletteIndex", 3f);
			component.anim.Play("Spawn");
			return component;
		}
	}
