using System.Collections;
using Chaos.AnimatorExtensions;
using UnityEngine;
[AddComponentMenu("Chaos/Enemies/Spider")]
public class Spider : Enemy
{
	public class PauseState : State<Spider>
	{
		public PauseState(string stateName, FSM parentFSM, Spider parentEntity)
			: base(stateName, parentFSM, parentEntity)
		{
		}
		public override void OnEnter()
		{
			parent.health.ignoreHurtVarStat.AddMod(Health.baseIgnoreMod);
			parent.anim.PlayDirectional("Idle" + parent.facingDirection);
			parent.movement.EndMovement();
		}
	}
	public new class ChaseState : State<Spider>
	{
		public ChaseState(string stateName, FSM parentFSM, Spider parentEntity)
			: base(stateName, parentFSM, parentEntity)
		{
		}
		public override void OnEnter()
		{
			parent.anim.PlayDirectional("Run" + parent.FaceTarget(parent.closestTargetInfo.position, 2));
			if (!parent.timerStarted)
			{
				parent.StartCoroutine(parent.ExplosionTimer());
				parent.timerStarted = true;
			}
		}
		public override void Update()
		{
			parent.closestTargetInfo = Entity.GetClosestTarget(parent.targetGroup, parent.transform.position, 9999f);
			if (parent.closestTargetInfo != null)
			{
				FacingDirection facingDirection = parent.facingDirection;
				parent.FaceTarget(parent.closestTargetInfo.position, 2);
				if (facingDirection != parent.facingDirection)
				{
					parent.anim.PlayDirectional("Run" + parent.facingDirection);
				}
				parent.movement.MoveToTarget(parent.closestTargetInfo.transform, parent.attackRadius);
			}
		}
	}
	public new class AttackState : State<Spider>
	{
		public AttackState(string stateName, FSM parentFSM, Spider parentEntity)
			: base(stateName, parentFSM, parentEntity)
		{
		}
		public override void OnEnter()
		{
			parent.anim.PlayDirectional(name);
			parent.movement.EndMovement();
		}
		public override void Update()
		{
			if (parent.anim.AnimPlayed())
			{
				parent.health.healthStat.CurrentValue = 0f;
				fsm.ChangeState("Dead");
				parent.health.ignoreHurtVarStat.RemoveMod(Health.baseIgnoreMod);
			}
		}
	}
	public float explosionTime;
	public float explosionPauseTime;
	private float timeUntilFlash;
	private int explosionStopwatchID;
	private int pauseStopwatchID;
	private int flashStopwatchID;
	public float speedRamp;
	private NumVarStatMod spiderSpeedUpMod;
	internal Light spiderLight;
	private CastingCircle castingCircle;
	private GameObject iceBombPrefab;
	private float explosionScale;
	internal bool timerStarted;
	public override void Awake()
	{
		base.Awake();
		InitFSM();
		InitAudio();
		explosionTime = 3.5f;
		explosionScale = 1.5f;
		iceBombPrefab = ChaosBundle.Get("Assets/Prefabs/Items/IceBomb.prefab");
		spiderSpeedUpMod = new NumVarStatMod("SpiderSpeedUpMod", movement.moveSpeedStat.CurrentValue, 10, VarStatModType.OverrideWithMods);
	}
	private new void InitFSM()
	{
		fsm = new FSM();
		fsm.defaultStateName = "Idle";
		fsm.AddState(new IdleState("Idle", fsm, this)
		{
			multiAnimIdle = true
		});
		fsm.AddState(new AttackState("Attack", fsm, this));
		fsm.AddState(new ChaseState("Chase", fsm, this));
		fsm.AddState(new PauseState("Pause", fsm, this));
		fsm.AddState(new EnemyDeadState("Dead", fsm, this));
		fsm.AddState(new EnemyHurtState("Hurt", fsm, this));
		fsm.AddState(new EnemyFallState("Fall", fsm, this));
		fsm.AddState(new EnemyFrozenState("Frozen", fsm, this));
		fsm.ChangeState(fsm.defaultStateName);
	}
	public override void InitComponents()
	{
		base.InitComponents();
		spiderLight = transform.Find("SpiderLight").GetComponent<Light>();
	}
	private new void InitAudio()
	{
		hurtAudioIDs = new string[1] { "SpiderHurt" };
		minPitch = 0.9f;
		maxPitch = 1.3f;
	}
	public IEnumerator ExplosionTimer()
	{
		timeUntilFlash = explosionTime * 0.08f;
		explosionStopwatchID = ChaosStopwatch.Begin(explosionTime);
		flashStopwatchID = ChaosStopwatch.Begin(timeUntilFlash);
		spiderLight.intensity = 1.6f;
		bool redPhase = true;
		float currentSpeed = movement.moveSpeedStat.CurrentValue;
		castingCircle = CastingCirclePool.Spawn("DrawInsideOut", transform.position, parentObj: gameObject, color: CastingCircle.enemyColor, drawTime: explosionPauseTime + explosionTime, disableWithParentVal: true, trackParentVal: true, useCastTimeVal: false, castTimeVal: 0f, unitSizeX: transform.localScale.x * ((CircleCollider2D)attack.collider).radius);
		while (!ChaosStopwatch.Check(explosionStopwatchID) && !fsm.currentStateName.Contains("Dead") && !fsm.currentStateName.Contains("Fall"))
		{
			currentSpeed += speedRamp * Time.deltaTime;
			spiderSpeedUpMod.modValue = currentSpeed;
			movement.moveSpeedStat.AddMod(spiderSpeedUpMod);
			if (ChaosStopwatch.Check(flashStopwatchID))
			{
				explosionTime -= timeUntilFlash;
				timeUntilFlash = explosionTime * 0.08f;
				flashStopwatchID = ChaosStopwatch.Begin(timeUntilFlash);
				spiderLight.intensity = ((!redPhase) ? 1.6f : 0f);
				redPhase = !redPhase;
			}
			yield return null;
		}
		movement.moveSpeedStat.RemoveMod(spiderSpeedUpMod.ID);
		movement.EndMovement();
		spiderLight.intensity = 3f;
		if (!fsm.currentStateName.Contains("Dead"))
		{
			fsm.ChangeState("Pause");
		}
		pauseStopwatchID = ChaosStopwatch.Begin(explosionPauseTime);
		while (!ChaosStopwatch.Check(pauseStopwatchID) && !fsm.currentStateName.Contains("Dead") && !fsm.currentStateName.Contains("Fall"))
		{
			yield return null;
		}
		if (fsm.currentStateName.Contains("Dead") || fsm.currentStateName.Contains("Fall"))
		{
			redPhase = false;
			spiderLight.intensity = 0f;
			yield break;
		}
		fsm.QueueChangeState("Attack");
		GameObject newExplosion = Object.Instantiate(iceBombPrefab, transform.position, Quaternion.Euler(0f, 0f, 0f));
		IceBomb newIceBomb = newExplosion.GetComponent<IceBomb>();
		newIceBomb.fuseDuration = 0f;
		newIceBomb.startHidden = true;
		newIceBomb.attackBox.SetAttackInfo(skillCategory, "FrostSpiderExplosion");
		newIceBomb.attackAllies = true;
		newExplosion.transform.SetParent(transform);
		redPhase = false;
		spiderLight.intensity = 0f;
		castingCircle.Reset();
		CameraController.ShakeCamera(2f);
	}
}
using System;
using UnityEngine;
public class SpikeSpider : Enemy
{
	public class SpiderIdleRoamState : IdleRoamState
	{
		public new SpikeSpider parent;
		public SpiderIdleRoamState(string name, FSM fsm, SpikeSpider ent)
			: base(name, fsm, ent)
		{
			parent = ent;
			multiAnimIdle = true;
		}
		public override void OnEnter()
		{
			base.OnEnter();
			parent.ToggleMoveSpeedUp(status: false);
		}
	}
	public class SpiderHurtState : EnemyHurtState
	{
		public new SpikeSpider parent;
		public SpiderHurtState(string name, FSM fsm, SpikeSpider ent)
			: base(name, fsm, ent)
		{
			parent = ent;
		}
		public override void OnEnter()
		{
			base.OnEnter();
			parent.ToggleMoveSpeedUp(status: true);
		}
	}
	public class SpiderDazedState(string name, FSM fsm, SpikeSpider ent) : State<SpikeSpider>(name, fsm, ent)
	{
		private float dazedDuration = 1f;
		private int dazedStopwatchID;
		public override void OnEnter()
		{
			dazedStopwatchID = ChaosStopwatch.Begin(dazedDuration);
			parent.anim.Play("IdleDown");
			parent.movement.EndMovement();
		}
		public override void Update()
		{
			if (ChaosStopwatch.Check(dazedStopwatchID))
			{
				fsm.ChangeState((!parent.alerted) ? fsm.defaultStateName : "Chase");
			}
		}
	}
	private NumVarStatMod alertedSpeedUpMod;
	private string speedUpString = "alertedSpeedUpMod";
	private float speedUpValue = 1.5f;
	public override void Awake()
	{
		base.Awake();
		alertedSpeedUpMod = new NumVarStatMod(speedUpString, movement.moveSpeedStat.CurrentValue * speedUpValue, 10, VarStatModType.OverrideWithMods);
	}
	public override void InitFSM()
	{
		fsm = new FSM();
		fsm.defaultStateName = "Idle";
		fsm.AddState(new RoamState("Roam", fsm, this));
		attackSkillID = "NeutralSpiderSpikes";
		fsm.AddState(new AttackState("Attack", fsm, this));
		fsm.AddState(new ChaseState("Chase", fsm, this));
		fsm.AddState(new EnemyDeadState("Dead", fsm, this));
		fsm.AddState(new EnemyFallState("Fall", fsm, this));
		fsm.AddState(new EnemyFrozenState("Frozen", fsm, this));
		fsm.AddState(new SpiderIdleRoamState("Idle", fsm, this));
		fsm.AddState(new SpiderHurtState("Hurt", fsm, this));
		fsm.AddState(new SpiderDazedState("Dazed", fsm, this));
		fsm.AddState(new LungeState("Lunge", fsm, this, 0, 1, 0f, 3f, 0f)
		{
			attackSkillID = "NeutralSpiderSpikeLunge",
			castingAnimName = "IdleDown",
			attackAnimName = "IdleDown",
			appendFacingDirectionToAtkAnim = false,
			dashSpeed = 20f,
			dashDuration = 0.2f
		});
		fsm.ChangeState(fsm.defaultStateName);
	}
	public override void InitAudio()
	{
		hurtAudioIDs = new string[1] { "SpiderHurt" };
		minPitch = 0.9f;
		maxPitch = 1.1f;
	}
	public override void Start()
	{
		base.Start();
		Attack attack = base.attack;
		attack.attackCollisionEventHandlers = (Attack.AttackCollisionEventHandler)Delegate.Combine(attack.attackCollisionEventHandlers, new Attack.AttackCollisionEventHandler(OnCollision));
		base.attack.SetAttackInfo(skillCategory, attackSkillID);
	}
	private void OnCollision(Collider2D col)
	{
		fsm.QueueChangeState("Dazed");
	}
	private void ToggleMoveSpeedUp(bool status)
	{
		if (status)
		{
			movement.moveSpeedStat.AddMod(alertedSpeedUpMod);
		}
		else
		{
			movement.moveSpeedStat.RemoveMod(alertedSpeedUpMod);
		}
	}
}

