			: base(newName, newFSM, newEnt)
		{
		}
		public override void OnEnter()
		{
			projReleased = false;
			parent.UpdateTargetInfo(parent.attackRadius, reqLOS: true);
			if (parent.closestTargetInfo == null || parent.closestTargetInfo.hurtBoxTransform == null)
			{
				parent.fsm.ChangeState(fsm.defaultStateName);
				return;
			}
			shootVector = (parent.closestTargetInfo.hurtBoxPosition - (parent.transform.position + Vector3.up)).normalized;
			string text = Globals.DirToAnimDir(Globals.GetDirFromAngle(Globals.GetRotationVector(shootVector).z));
			if (text.Contains("Left"))
			{
				parent.isFacingRight = false;
				parent.facingDirection = FacingDirection.Left;
			}
			else
			{
				parent.isFacingRight = true;
				parent.facingDirection = FacingDirection.Right;
			}
			string animationName = "Shoot" + text;
			parent.anim.PlayDirectional(animationName);
		}
		public override void Update()
		{
			if (projReleased || parent.anim.AnimPlayed(0.5f))
			{
				if (!projReleased)
				{
					Projectile projectile = CreateProjectile();
					projectile.moveVector = shootVector;
					projectile.attackBox.collider.enabled = true;
					SoundManager.PlayAudioWithDistance(parent.attackAudioID, parent.transform.position);
					projReleased = true;
				}
				else if (parent.anim.AnimPlayed())
				{
					parent.fsm.ChangeState(fsm.defaultStateName);
				}
			}
		}
