using UnityEngine;
public class BossDummy : TrainingDummy
{
	public class BossDummyHurtState : HurtState
	{
		private float baseHurtDuration = 0.9f;
		private float maxHurtDuration = 1.8f;
		private int hurtStopwatchID;
		private float stunOverrideValue = 2f;
		private AttackInfo lastAtkInfo;
		private int minComboCount = 5;
		private int hitCounter;
		public new BossDummy parent;
		public BossDummyHurtState(string newName, FSM newFSM, BossDummy newEnt)
			: base(newName, newFSM, newEnt)
		{
			parent = newEnt;
			Reset();
		}
		public override void OnEnter()
		{
			parent.anim.Play("Hurt", -1, 0f);
			lastAtkInfo = parent.health.lastAttack;
			if (fsm.previousStateName != name)
			{
				HandleDurationIncrease(first: true);
			}
			else
			{
				HandleDurationIncrease();
			}
			HandleStunEffect();
			if (parent.health != null)
			{
				parent.ApplyKnockback(lastAtkInfo);
			}
			if (hitCounter >= minComboCount)
			{
				GameUI.BroadcastNoticeMessage(hitCounter + TextManager.GetUIText("bossRoom-comboCounter"));
			}
		}
		public override void Update()
		{
			exitHurtState = ChaosStopwatch.Check(hurtStopwatchID);
			if (exitHurtState)
			{
				if (hitCounter >= minComboCount)
				{
					GameController.stageTitleUI.AnnounceCombo(hitCounter);
				}
				ExitTransition();
			}
		}
		public override void OnExit()
		{
			if (!parent.fsm.nextStateName.Contains("Hurt"))
			{
				Reset();
			}
		}
		public virtual void Reset(bool playStunRecoveryFX = true)
		{
			hitCounter = 0;
			if (stunEffect != null)
			{
				stunEffect.Stop(playRecoveryFX: true);
				stunEffect = null;
			}
		}
		public virtual void HandleDurationIncrease(bool first = false)
		{
			if (first)
			{
				hitCounter = 1;
				hurtStopwatchID = ChaosStopwatch.Begin(baseHurtDuration);
				return;
			}
			if (lastAtkInfo != null && !lastAtkInfo.isStatusEffect)
			{
				hitCounter++;
			}
			hurtStopwatchID = ChaosStopwatch.Begin(Mathf.Min(maxHurtDuration, baseHurtDuration / (float)hitCounter + ChaosStopwatch.GetRemainingTime(hurtStopwatchID)));
		}
		public virtual void HandleStunEffect()
		{
			if (base.stunEffect == null)
			{
				base.stunEffect = PoolManager.GetPoolItem<StunEffect>();
				base.stunEffect.fullStunOverride = stunOverrideValue;
				base.stunEffect.Play(hurtStopwatchID, parent.transform, Vector3.up * 2.75f);
			}
			else
			{
				StunEffect stunEffect = base.stunEffect;
				int givenStopwatchID = hurtStopwatchID;
				stunEffect.Readjust(-1f, givenStopwatchID);
			}
		}
	}
	public override void InitFSM()
	{
		base.InitFSM();
		fsm.ReplaceState(new BossDummyHurtState("Hurt", fsm, this));
	}
	public override void Start()
	{
		base.Start();
		health.knockbackModifierStat.AddMod(new NumVarStatMod("BossKnockback", 0.25f, 10, VarStatModType.Override));
	}
}

