		public new LaserOrb parent;
		public LaserOrbAttackState(string newName, FSM newFSM, LaserOrb newEnt, int newReq, int newPriority, float newMin, float newMax, float newCD, bool newAuto = true)
			: base(newName, newFSM, newEnt, newReq, newPriority, newMin, newMax, newCD, newAuto)
		{
