			exitTime = StdExitTime;
			chargeEffect = PoolManager.GetPoolItem<ParticleEffect>("ChaosChargeEffect");
			ParticleEffect particleEffect = chargeEffect;
			float? emissionRate = 3f;
			Vector3? position = parent.attackOriginTrans.position;
			float? playTime = StdWindupTime * 0.75f;
			particleEffect.Play(emissionRate, position, null, playTime);
			blobChargeEffect = PoolManager.GetPoolItem<ParticleEffect>("ChaosBlobChargeEffect");
			ParticleEffect particleEffect2 = blobChargeEffect;
			playTime = 30f;
			position = parent.attackOriginTrans.position;
			emissionRate = StdWindupTime * 0.5f;
			particleEffect2.Play(playTime, position, null, emissionRate);
			parent.auraEmitter.Stop();
			lasersCreated = false;
			firstFrame = true;
		}
		public override void WindupUpdate()
		{
			if (firstFrame)
			{
				firstFrame = false;
			}
			else if (!lasersCreated)
			{
				lasersCreated = true;
				CreateLasers(parent.attackOriginTrans.position);
			}
		}
		public override void ExecuteSkill()
		{
			base.ExecuteSkill();
			parent.anim.Play(attackAnimName);
			for (int i = 0; i < numberOfShots; i++)
			{
				lbArray[i].Blast();
			}
