				{
					lbArray[i].Reset();
				}
			}
			parent.auraEmitter.Play();
			chargeEffect.Stop();
			chargeEffect.effectEmitter.Clear();
			blobChargeEffect.Stop();
			blobChargeEffect.effectEmitter.Clear();
		}
		public override void ExitTransition()
		{
