			}
			else
			{
				fsm.ChangeState(fsm.defaultStateName);
			}
		}
		private void CreateLasers(Vector2 givenPosition)
		{
			initDirection = UnityEngine.Random.Range(0, maxDirections);
			for (int i = 0; i < numberOfShots; i++)
			{
				targetVector = Globals.GetCirclePositionVector(maxDirections, (initDirection + i * 2) % maxDirections);
				lbArray[i] = Globals.ChaosInst<LaserBeam>(LaserBeam.Prefab, parent.transform, givenPosition, Globals.GetRotationQuaternion(targetVector));
				lbArray[i].attack.SetAttackInfo(parent.skillCategory, "NeutralLaserOrbAttack");
