		currentLaser.timeTilMaxRange = 1f;
		currentLaser.flashDuringCharge = true;
		currentLaser.flashThreshold = 0.5f;
		currentLaser.hitCooldownTime = 0.06f;
	}
	public void SetLaserAttackInfo()
	{
