	public float spawnTimer;
	private int spawnStopwatchID = -1;
	public int maxSpawnCycles;
	public int currentSpawnCycle;
	public int enemiesPerCycle;
	public Vector2 spawnOrigin;
	public Vector2 spawnArea;
	public Vector2 invalidSpawnOrigin;
	public Vector2 invalidSpawnArea;
