	private Vector3 invalidBotRight;
	private Vector3 invalidTopLeft;
	[HideInInspector]
	public Transform enemyLocations;
	public List<Enemy> spawnedEnemies;
	private GameObject enemyPrefab;
	public static GameObject Prefab => prefab ?? (prefab = ChaosBundle.Get("Assets/Prefabs/Environment/EnemyFactory.prefab"));
	private void Awake()
	{
		InitEnemyContainer();
		spawnedEnemies = new List<Enemy>();
		wasActivated = spawning;
	}
	private void Start()
	{
		enemyPrefab = ChaosBundle.Get(Enemy.enemyPrefabPaths[enemyPrefabKey]);
		SetSpawnAreaExtents();
	}
	private void Update()
	{
		if (!spawning)
		{
			wasSpawning = false;
			return;
		}
		if (!wasSpawning)
		{
			wasSpawning = true;
 Random.Range(1f, spawnTimer));
		}
		if (maxSpawnCycles >= 0 && currentSpawnCycle >= maxSpawnCycles)
		{
			spawning = false;
		}
		else if (ChaosStopwatch.Check(spawnStopwatchID))
		{
			wasActivated = true;
			for (int i = 0; i < enemiesPerCycle; i++)
			{
 false, spawnCard: true, autoAlertEnemies, disableCountDeath);
				spawnedEnemies.Add(enemy);
				enemy.parentFactoryList = spawnedEnemies;
			}
 Random.Range(1f, spawnInterval));
			currentSpawnCycle++;
		}
	}
	public bool AllEnemiesCleared()
	{
		if (!wasActivated || spawning)
		{
			return false;
		}
		foreach (Enemy spawnedEnemy in spawnedEnemies)
		{
			if (spawnedEnemy != null && (spawnedEnemy.health.healthStat.CurrentValue > 0f || !spawnedEnemy.fsm.currentStateName.Contains("Dead")))
			{
				return false;
			}
		}
		return true;
	}
	private void InitEnemyContainer()
	{
		Transform transform = base.transform.root.Find("EnemyLocations");
		if (transform == null)
		{
			transform = base.transform.root.Find("Enemies");
		}
		if (transform == null && base.transform.parent != null)
		{
			transform = base.transform.parent.Find("Enemies");
		}
		if (transform == null)
		{
			transform = new GameObject("Enemies").transform;
			transform.SetParent(base.transform.parent);
		}
		enemyLocations = transform;
	}
	private void SetSpawnAreaExtents()
	{
		spawnOriginWorld = transform.TransformPoint(spawnOrigin);
		halfArea = spawnArea * 0.5f;
		botLeft = spawnOriginWorld - halfArea;
		topRight = spawnOriginWorld + halfArea;
		botRight = new Vector2(spawnOriginWorld.x + halfArea.x, spawnOriginWorld.y - halfArea.y);
		topLeft = new Vector2(spawnOriginWorld.x - halfArea.x, spawnOriginWorld.y + halfArea.y);
		invalidSpawnOriginWorld = transform.TransformPoint(invalidSpawnOrigin);
		invalidHalfArea = invalidSpawnArea * 0.5f;
		invalidBotLeft = invalidSpawnOriginWorld - invalidHalfArea;
		invalidTopRight = invalidSpawnOriginWorld + invalidHalfArea;
		invalidBotRight = new Vector2(invalidSpawnOriginWorld.x + invalidHalfArea.x, invalidSpawnOriginWorld.y - invalidHalfArea.y);
		invalidTopLeft = new Vector2(invalidSpawnOriginWorld.x - invalidHalfArea.x, invalidSpawnOriginWorld.y + invalidHalfArea.y);
	}
	private Vector3 GetRandomLocation()
	{
		if (spawnArea == Vector2.zero)
		{
			return spawnOriginWorld;
		}
		int num = 0;
		if (invalidSpawnArea != Vector2.zero)
		{
			num = Random.Range(1, 5);
		}
		return num switch
		{
			1 => new Vector3(Random.Range(botLeft.x, invalidBotLeft.x), Random.Range(botLeft.y, topLeft.y)), 
			2 => new Vector3(Random.Range(invalidBotRight.x, botRight.x), Random.Range(botLeft.y, topLeft.y)), 
			3 => new Vector3(Random.Range(invalidBotLeft.x, invalidBotRight.x), Random.Range(invalidTopLeft.y, topLeft.y)), 
			4 => new Vector3(Random.Range(invalidBotLeft.x, invalidBotRight.x), Random.Range(botLeft.y, invalidBotLeft.y)), 
			_ => new Vector3(Random.Range(botLeft.x, botRight.x), Random.Range(botLeft.y, topLeft.y)), 
		};
	}
	private void OnDrawGizmosSelected()
	{
		SetSpawnAreaExtents();
		Gizmos.color = Color.green;
		Gizmos.DrawLine(botLeft, topLeft);
		Gizmos.DrawLine(topLeft, topRight);
		Gizmos.DrawLine(topRight, botRight);
		Gizmos.DrawLine(botLeft, botRight);
		Gizmos.color = Color.red;
		Gizmos.DrawLine(invalidBotLeft, invalidTopRight);
		Gizmos.DrawLine(invalidTopLeft, invalidBotRight);
		Gizmos.DrawLine(invalidBotLeft, invalidTopLeft);
		Gizmos.DrawLine(invalidTopLeft, invalidTopRight);
		Gizmos.DrawLine(invalidTopRight, invalidBotRight);
		Gizmos.DrawLine(invalidBotLeft, invalidBotRight);
		if (invalidSpawnArea.x > spawnArea.x - 2f)
		{
			invalidSpawnArea.x = spawnArea.x - 2f;
			invalidSpawnOrigin.x = spawnOrigin.x;
		}
		if (invalidSpawnArea.y > spawnArea.y - 2f)
		{
			invalidSpawnArea.y = spawnArea.y - 2f;
			invalidSpawnOrigin.y = spawnOrigin.y;
		}
		if (invalidTopLeft.x < botLeft.x + 1f)
		{
			invalidSpawnOrigin.x += botLeft.x + 1f - invalidTopLeft.x;
		}
		if (invalidTopRight.x > topRight.x - 1f)
		{
			invalidSpawnOrigin.x += topRight.x - 1f - invalidTopRight.x;
		}
		if (invalidBotLeft.y < botLeft.y + 1f)
		{
			invalidSpawnOrigin.y += botLeft.y + 1f - invalidBotLeft.y;
		}
		if (invalidTopRight.y > topRight.y - 1f)
		{
			invalidSpawnOrigin.y += topRight.y - 1f - invalidTopRight.y;
		}
		if (invalidSpawnArea.x < 0f || invalidSpawnArea.y < 0f)
		{
			invalidSpawnArea = Vector2.zero;
		}
	}
	public void ResetFactory()
	{
		spawning = false;
		wasSpawning = false;
		wasActivated = false;
		currentSpawnCycle = 0;
		spawnStopwatchID = -1;
		foreach (Enemy spawnedEnemy in spawnedEnemies)
		{
			if (!(spawnedEnemy == null) && !(spawnedEnemy.gameObject == null) && !(spawnedEnemy.fsm.currentStateName == "Dead"))
			{
				spawnedEnemy.dropLoot = false;
				spawnedEnemy.dropLootChest = false;
				if (spawnedEnemy.fsm.HasState("Dead"))
				{
					spawnedEnemy.fsm.QueueChangeState("Dead");
					continue;
				}
				Object.Destroy(spawnedEnemy.gameObject);
				Enemy.SpawnEnemyPortal(spawnedEnemy.transform.position);
			}
		}
		spawnedEnemies.Clear();
	}
}

